
export const realestatePrompts = [

    // --- PROPERTY VALUATION (1-8) ---
    {"id":"re-1","title":"Multifamily Investment Underwriting","prompt":"You are a commercial real estate analyst specializing in multifamily investment underwriting. Underwrite a 48-unit apartment complex in a secondary Midwest market (Columbus, Ohio suburb) with the following details: asking price $7.2M, current gross rental income $684,000/year (average $1,187/unit/month), vacancy rate 6%, operating expenses $285,000/year (42% expense ratio), and the property is 1987 vintage needing $2,400/unit in deferred maintenance. The buyer plans to finance with a 70% LTV loan at 6.8% interest rate, 30-year amortization, 5-year term. Perform a full underwriting analysis including: Year 1 NOI calculation, going-in cap rate, debt service coverage ratio, cash-on-cash return, and equity multiple. Then model a value-add scenario: $3,000/unit renovation to 30 units over 24 months, pushing rents from $1,187 to $1,420/month on renovated units with 8% vacancy during renovation. Calculate the stabilized NOI, projected exit cap rate at 5.5%, and 5-year IRR assuming a sale at the end of Year 5. Identify the two biggest risks in this deal.","tags":["valuation","investment","underwriting","multifamily"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},

    {"id":"re-2","title":"Comparable Sales Adjustment Grid","prompt":"You are a certified residential appraiser. A subject property is a 2,100 sq ft, 4-bed/2-bath single-family home built in 1998 with a 2-car garage, updated kitchen, and no pool, located in a suburban Phoenix neighborhood. Three comparable sales have closed in the past 90 days: Comp 1 — 1,950 sq ft, 3-bed/2-bath, 2001 vintage, 2-car garage, no pool, sold for $485,000; Comp 2 — 2,200 sq ft, 4-bed/2.5-bath, 1995 vintage, no garage, pool, sold for $510,000; Comp 3 — 2,050 sq ft, 4-bed/2-bath, 2000 vintage, 1-car garage, no pool, sold for $492,000. Build a complete adjustment grid. Use $15,000 per bedroom, $10,000 per bathroom, $25 per sq ft for size, $8,000 for garage bay, and $20,000 for pool. Show the adjusted sale price for each comp, then reconcile to a final opinion of value with a brief written narrative justifying your reconciliation weighting.","tags":["valuation","appraisal","residential","comps"],"author":"AINOW","created":"2024-02-15T10:05:00Z","featured":false},

    {"id":"re-3","title":"Income Approach: Office Building Valuation","prompt":"You are a commercial appraiser valuing a 22,000 sq ft suburban office building using the income approach. The building is 88% occupied. Lease details: Tenant A occupies 10,000 sq ft at $24/sq ft NNN with 3 years remaining; Tenant B occupies 7,000 sq ft at $21/sq ft NNN with 1 year remaining; Tenant C occupies 2,360 sq ft at $23/sq ft NNN with 18 months remaining; the remaining 2,640 sq ft is vacant. Market rent for comparable office space is $23/sq ft NNN. Operating expenses for the landlord (management, insurance, reserves, non-recoverable) are $3.80/sq ft on occupied space. Vacancy and collection loss allowance is 8% on market rents for rollover risk. Step through the full income approach: calculate potential gross income, effective gross income, net operating income, and then apply a market cap rate of 7.25% to derive value. Then perform a sensitivity analysis showing value at cap rates of 6.75%, 7.25%, and 7.75%.","tags":["valuation","commercial","office","income-approach"],"author":"AINOW","created":"2024-02-15T10:10:00Z","featured":false},

    {"id":"re-4","title":"Discounted Cash Flow Model — Retail Strip Center","prompt":"You are a real estate investment analyst. Build a 10-year discounted cash flow model for a 15,000 sq ft retail strip center purchased for $3.2M. Current in-place NOI is $208,000 (6.5% cap rate). Assume: annual rent escalations of 2.5%, vacancy allowance of 7%, capital expenditure reserve of $0.50/sq ft/year, management fee of 4% of EGI, and a terminal cap rate of 7.0% at the end of Year 10. Financing: 65% LTV at 6.5% interest, 25-year amortization. Calculate annual cash flows, debt service, before-tax cash flow, and the reversion value in Year 10. Derive the NPV at a 9% discount rate and the unleveraged IRR. Present results in a clean table format and identify the Year 10 exit assumptions that most heavily influence total return.","tags":["valuation","dcf","retail","investment"],"author":"AINOW","created":"2024-02-15T10:15:00Z","featured":true},

    {"id":"re-5","title":"Land Valuation: Residual Method","prompt":"You are a development consultant valuing a 2.5-acre infill site in an urban market using the residual land value method. The site is zoned for a 60-unit condominium project. Development assumptions: average unit size 950 sq ft, average sale price $425/sq ft ($403,750/unit), total construction cost $185/sq ft hard costs plus $35/sq ft soft costs, developer profit requirement of 18% on total cost (excluding land), financing carry cost of $420,000 for an 18-month construction period at 7.5% interest, and sales/marketing costs of 4% of gross revenue. Walk through each step of the residual calculation to arrive at the maximum supportable land value. Then explain how a 10% drop in condo sale prices or a $15/sq ft increase in hard costs would each affect the residual land value, and identify the threshold at which the project becomes infeasible.","tags":["valuation","land","development","residual-method"],"author":"AINOW","created":"2024-02-15T10:20:00Z","featured":false},

    {"id":"re-6","title":"Property Valuation Report from Financials","prompt":"You are a senior real estate analyst. Review the property financials below and produce a concise valuation summary. Include: stabilized NOI, going-in cap rate implied by asking price (if provided), DCF value at a 9% discount rate, and a brief narrative on the key value drivers and risks.\n\n[Paste the property details, financials, or listing description]","tags":["valuation","analysis","finance","reporting"],"author":"AINOW","created":"2024-02-15T10:25:00Z","featured":false},

    {"id":"re-7","title":"Cap Rate Spread Analysis by Market Tier","prompt":"You are a real estate capital markets analyst. Explain the concept of cap rate compression and expansion in the context of the current interest rate environment. Compare going-in cap rates across four asset classes (multifamily, industrial, office, retail) in three market tiers (gateway cities like NYC/LA, secondary markets like Denver/Nashville, and tertiary markets like Boise/Knoxville). Discuss the cap rate spread to the 10-year Treasury and what historical spread compression tells us about pricing risk. Then explain three scenarios — soft landing, prolonged high rates, and a recession — and how each would likely affect cap rates and asset values across these combinations of asset class and market tier over a 24-month horizon.","tags":["valuation","capital-markets","cap-rates","market-analysis"],"author":"AINOW","created":"2024-02-15T10:30:00Z","featured":false},

    {"id":"re-8","title":"Automated Valuation Model (AVM) Critique","prompt":"You are a real estate technology consultant and appraiser. A homeowner has received three automated valuations for their property: Zillow Zestimate at $612,000, Redfin Estimate at $587,000, and a bank AVM at $601,000. The actual property has a recently finished basement (900 sq ft not in public records), a new HVAC system, and backs to a greenbelt — none of which AVMs can detect. Explain in plain language how AVMs work, what data sources they use, and why they systematically fail for properties with non-permitted improvements, unique amenities, or thin comparable sales. Outline the five most common AVM failure modes and advise the homeowner on how to document and present evidence to support a higher value to a lender or buyer.","tags":["valuation","technology","avm","residential"],"author":"AINOW","created":"2024-02-15T10:35:00Z","featured":false},

    // --- REAL ESTATE INVESTMENT ANALYSIS (9-16) ---
    {"id":"re-9","title":"BRRRR Strategy Deep Dive","prompt":"You are a real estate investment coach specializing in the BRRRR strategy (Buy, Rehab, Rent, Refinance, Repeat). Walk through a complete end-to-end BRRRR deal in a Midwest market. The investor buys a distressed single-family home for $95,000 cash, spends $42,000 on renovation over 4 months, achieving an ARV of $195,000. After renovation, the property rents for $1,650/month. The investor does a cash-out refinance at 75% LTV based on ARV. Calculate: total capital invested before refinance, refinance proceeds, cash left in the deal after refinance, monthly cash flow after PITI (6.75% rate, 30-year term), cash-on-cash return on remaining equity, and total return if the property appreciates 3% annually over 5 years and is sold. Identify the three most common mistakes investors make in each phase of BRRRR and how to avoid them.","tags":["investment","brrrr","residential","strategy"],"author":"AINOW","created":"2024-02-15T10:40:00Z","featured":false},

    {"id":"re-10","title":"House Hacking Analysis","prompt":"You are a personal finance and real estate advisor. Analyze a house hacking strategy for a first-time buyer in Austin, Texas. The buyer purchases a 4-unit property for $680,000 using an FHA loan (3.5% down, 6.9% rate, 30-year term, 1.75% upfront MIP, 0.85% annual MIP). The buyer occupies one unit and rents the other three at $1,450/month each. Operating expenses: property taxes $9,200/year, insurance $3,600/year, maintenance reserve 8% of gross rents, vacancy allowance 6%, management (self-managed, $0). Calculate: total monthly PITI, gross rent from three units, net operating income, monthly out-of-pocket housing cost after rent income, effective rent per square foot, and cash-on-cash return. Then compare this to renting a comparable apartment at $2,200/month and quantify the total 5-year wealth-building advantage of house hacking including principal paydown and estimated appreciation.","tags":["investment","house-hacking","residential","first-time-buyer"],"author":"AINOW","created":"2024-02-15T10:45:00Z","featured":false},

    {"id":"re-11","title":"1031 Exchange Strategy Planner","prompt":"You are a tax-deferred exchange specialist. An investor is selling a commercial building for $2.8M with a cost basis of $900,000 (after depreciation), creating a $1.9M gain. The investor is in the 20% capital gains bracket plus 3.8% net investment income tax, and has $630,000 in accumulated depreciation subject to 25% recapture. Calculate the total tax liability if they sell without a 1031 exchange. Then plan a 1031 exchange strategy: explain the 45-day identification rule, the 180-day closing rule, the three-property identification rule, and the equal-or-greater value requirement. Propose three replacement property scenarios at different price points ($2.8M, $3.5M, $4.2M) and explain how each affects the deferred tax, new basis, and future depreciation schedule. Identify the three most common 1031 exchange pitfalls that cause investors to inadvertently trigger a taxable event.","tags":["investment","1031-exchange","tax","strategy"],"author":"AINOW","created":"2024-02-15T10:50:00Z","featured":true},

    {"id":"re-12","title":"Real Estate Portfolio Stress Test","prompt":"You are a real estate portfolio risk analyst. An investor owns five properties: (1) 12-unit apartment building, $1.8M value, $980K mortgage at 4.2% fixed; (2) single-family rental, $420K value, $260K mortgage at 3.8% fixed; (3) small retail strip, $1.1M value, $720K at 5.9% variable rate ARM resetting in 18 months; (4) a vacant land parcel, $185K value, no debt; (5) an STR condo, $310K value, $220K at 6.5% fixed. Total gross rental income is $312,000/year. Run a stress test across three scenarios: Scenario A — 15% value decline and 10% rent decline; Scenario B — 200 bps rate increase on the ARM at reset and 20% STR revenue decline due to regulatory changes; Scenario C — combined recession (25% value decline, 15% rent decline, ARM resets at +250 bps, and 30% STR decline). For each scenario, calculate portfolio LTV, DSCR, and monthly cash flow. Identify the single greatest risk and recommend two specific portfolio actions to improve resilience.","tags":["investment","portfolio","risk","stress-test"],"author":"AINOW","created":"2024-02-15T10:55:00Z","featured":false},

    {"id":"re-13","title":"Opportunity Zone Investment Analysis","prompt":"You are a tax attorney and real estate investment advisor specializing in Qualified Opportunity Zones (QOZs). Explain the three tiers of QOZ tax benefits: deferral of capital gains until 2026, the 10% step-up in basis for investments held 5 years, and the complete exclusion of appreciation for investments held 10+ years. Then analyze a specific scenario: an investor has a $500,000 capital gain from a stock sale and invests it in a QOZ real estate development fund within 180 days. The fund develops a mixed-use project and the investor's stake grows to $1.4M over 10 years. Calculate the total tax savings compared to a traditional real estate investment, explain the 'substantially all' requirement for tangible property, the original use and substantial improvement tests, and identify three red flags that indicate a QOZ fund may not meet IRS requirements.","tags":["investment","opportunity-zone","tax","development"],"author":"AINOW","created":"2024-02-15T11:00:00Z","featured":false},

    {"id":"re-14","title":"Short-Term vs. Long-Term Rental Comparison","prompt":"You are a rental property analyst. Compare the financial performance of operating a property as a short-term rental (STR/Airbnb) versus a long-term rental (LTR) for the same property: a 3-bed/2-bath home in Scottsdale, Arizona valued at $575,000. STR scenario: average daily rate $225, occupancy 68%, platform fees 3%, cleaning $85/turnover (average 3 nights per stay), supplies/toiletries $1,200/year, STR management company 25% of revenue, furnishing cost $22,000 amortized over 5 years. LTR scenario: monthly rent $2,650, vacancy 5%, management fee 8%, tenant pays utilities. Both scenarios share: mortgage (70% LTV at 6.75%, 30-year), property taxes $7,200/year, insurance $2,400/year (STR requires higher rider), maintenance reserve 1% of value/year. Calculate annual gross revenue, NOI, cash flow, and cash-on-cash return for both. Factor in the $22,000 furnishing capital outlay for STR. Identify three non-financial considerations (regulatory risk, time commitment, wear and tear) that should influence the decision.","tags":["investment","str","ltr","rental-analysis"],"author":"AINOW","created":"2024-02-15T11:05:00Z","featured":false},

    {"id":"re-15","title":"Real Estate Syndication Deal Evaluation","prompt":"You are a passive real estate investor evaluating a syndication offering. The sponsor is presenting a 120-unit Class B multifamily value-add deal in Charlotte, NC. The offering documents show: purchase price $14.4M, total equity raise $5.2M, preferred return 7%, equity split 70/30 (LP/GP) above preferred, projected hold period 5 years, projected investor IRR 16.8%, equity multiple 2.1x. The business plan calls for renovating 80 units at $12,000/unit and raising rents by $220/month on renovated units. Critically evaluate this deal: calculate whether the projected IRR is achievable given the renovation budget and rent premium, assess the sponsor's equity split and fee structure (assume 2% acquisition fee and 1.5% asset management fee), and identify the five most important due diligence questions to ask the sponsor about their track record, the market, the financing terms, and the exit assumptions. Then describe three scenarios where passive investors lose money in multifamily syndications despite strong projections.","tags":["investment","syndication","multifamily","due-diligence"],"author":"AINOW","created":"2024-02-15T11:10:00Z","featured":false},

    {"id":"re-16","title":"Investment Property Due Diligence Checklist","prompt":"You are a commercial real estate attorney and investor. A buyer is under contract on an 18-unit apartment building for $2.6M. Create a comprehensive due diligence checklist organized into six categories: (1) Physical/Property — what to inspect and who to hire; (2) Financial — which documents to request and what anomalies to look for in rent rolls, T-12 operating statements, and tax returns; (3) Legal/Title — lien searches, encumbrances, easements, deed restrictions; (4) Environmental — when to order Phase I vs. Phase II, common issues in residential multifamily; (5) Market — how to validate the rent assumptions and vacancy rate; (6) Financing — what lenders will require and common conditions. For each category, list five specific action items and flag the two most common deal-killer discoveries investors miss during due diligence.","tags":["investment","due-diligence","multifamily","checklist"],"author":"AINOW","created":"2024-02-15T11:15:00Z","featured":false},

    // --- COMMERCIAL REAL ESTATE (17-24) ---
    {"id":"re-17","title":"Office Market Recovery Analysis","prompt":"You are a commercial real estate market strategist. Analyze the structural shift in the office market since 2020 and its investment implications. Address the following: (1) The difference between Class A trophy office (flight-to-quality) and Class B/C office (functional obsolescence) and why their performance has diverged sharply; (2) The current state of sublease availability as a leading indicator of tenant demand; (3) How hybrid work policies (2-3 days in office) translate into actual space requirements per employee compared to pre-pandemic norms; (4) The conversion opportunity — which office buildings are physically suitable for residential or mixed-use conversion and what makes a floor plate 'convertible'; (5) Distressed office debt — explain the loan maturity wall, bid-ask spread between buyers and lenders, and why many buildings are being returned to lenders. Conclude with a framework for determining whether a specific office asset represents a distressed opportunity or a value trap.","tags":["commercial","office","market-analysis","strategy"],"author":"AINOW","created":"2024-02-15T11:20:00Z","featured":true},

    {"id":"re-18","title":"Industrial Real Estate Investment Thesis","prompt":"You are an industrial real estate analyst. Build an investment thesis for last-mile industrial/logistics properties in major metropolitan markets. Structure your analysis around: (1) Demand drivers — e-commerce penetration rates, same-day/next-day delivery requirements, and the 'last mile premium' in land-constrained markets; (2) Supply constraints — zoning barriers, NIMBYism, truck traffic opposition, and entitlement timelines that create high barriers to entry; (3) Tenant credit quality — differentiate between investment-grade 3PLs, e-commerce giants, and small-business tenants, and how credit quality affects cap rate and financing; (4) Lease structure — explain NNN vs. gross leases, rent bumps (flat vs. CPI-linked), and why industrial leases historically underpriced inflation risk; (5) Valuation — current cap rates for Class A industrial, rent growth projections, and where the market is in the cycle. Identify two metros where you see the strongest risk-adjusted opportunities and two where the market is overheated.","tags":["commercial","industrial","investment","market-analysis"],"author":"AINOW","created":"2024-02-15T11:25:00Z","featured":true},

    {"id":"re-19","title":"Retail Leasing Strategy for Landlord","prompt":"You are a retail leasing director for a 180,000 sq ft regional lifestyle center that is 78% occupied. The center has three anchor spaces: one occupied by a fitness club (40,000 sq ft, 8 years remaining on lease), one dark since a department store closure (60,000 sq ft), and one occupied by a grocery store (35,000 sq ft, 3 years remaining with renewal options). Develop a leasing strategy for the dark anchor space. Analyze: (1) The feasibility of subdividing the 60,000 sq ft into 4-6 inline spaces vs. attracting a single replacement anchor; (2) The top five replacement anchor categories (entertainment, medical, education, fitness, grocery) and their relative ability to drive foot traffic and support inline tenant sales; (3) How to structure a below-market lease with a percentage rent override to attract an anchor tenant while protecting NOI; (4) The co-tenancy clause risk if the grocery anchor does not renew — how this could trigger rent reductions or termination rights for inline tenants. Recommend a prioritized action plan.","tags":["commercial","retail","leasing","strategy"],"author":"AINOW","created":"2024-02-15T11:30:00Z","featured":false},

    {"id":"re-20","title":"Data Center Real Estate Fundamentals","prompt":"You are a specialized commercial real estate advisor covering data center assets. Explain the fundamentals of data center real estate to a generalist investor considering entering the sector. Cover: (1) The key physical and infrastructure requirements that distinguish data centers from conventional industrial (power capacity measured in MW, cooling infrastructure, fiber connectivity, generator redundancy, PUE efficiency ratios); (2) The three tenant types — hyperscalers (AWS/Azure/Google), enterprise, and co-location — and how each affects lease structure, credit quality, and cap rates; (3) How to underwrite a data center acquisition — critical due diligence items around power contracts, cooling systems, and tenant concentration; (4) Why data centers trade at lower cap rates than conventional industrial and what risk factors justify the premium pricing; (5) The key markets (Northern Virginia, Dallas, Phoenix, Chicago) and what drives market selection. Identify two risks specific to data center investing that investors often underestimate.","tags":["commercial","data-center","investment","niche"],"author":"AINOW","created":"2024-02-15T11:35:00Z","featured":false},

    {"id":"re-21","title":"Commercial Lease Abstract","prompt":"You are a commercial real estate paralegal and tenant representative. Review the lease document below and produce a structured lease abstract. Extract and summarize: tenant name and entity type, premises square footage and suite number, lease commencement and expiration dates, base rent schedule with all escalations, rent abatement periods, security deposit amount and burn-down schedule, permitted use clause, exclusive use restrictions, co-tenancy clause (if any), assignment and subletting rights, renewal option terms and notice requirements, termination rights, landlord work obligations and tenant improvement allowance, operating expense inclusion/exclusion definitions, CAM cap provisions, and holdover rent provisions.\n\n[Paste the property details, financials, or listing description]","tags":["commercial","leasing","legal","analysis"],"author":"AINOW","created":"2024-02-15T11:40:00Z","featured":false},

    {"id":"re-22","title":"NNN Lease Investment Analysis","prompt":"You are a net lease investment advisor. Analyze the investment merits of a single-tenant NNN property: a 4,200 sq ft fast-casual restaurant on a hard corner in suburban Dallas, leased to a franchisee-operated national brand, asking price $2.85M, 12 years remaining on a 20-year absolute NNN lease, annual rent $171,000 ($40.71/sq ft), 10% rent bumps every 5 years, corporate guarantee (not franchisee). Calculate the going-in cap rate. Then evaluate five key investment risks: (1) tenant credit — franchisee versus corporate guarantee; (2) real estate fundamentals — what happens to the land and building if the tenant vacates; (3) lease expiration risk — resale value with 12 vs. 5 vs. 0 years remaining; (4) interest rate sensitivity — show the price impact at cap rates of 4.5%, 5.0%, 5.5%, and 6.0%; (5) dark value — how to estimate the property value as vacant land or with an alternative tenant. Conclude with a hold/pass recommendation and the minimum cap rate you would require to invest given current 10-year Treasury rates.","tags":["commercial","nnn","investment","single-tenant"],"author":"AINOW","created":"2024-02-15T11:45:00Z","featured":false},

    {"id":"re-23","title":"Mixed-Use Development Feasibility","prompt":"You are a real estate development consultant. A developer owns a 1.2-acre urban infill site zoned for mixed-use development in a mid-size Sun Belt city. The site can support 8,000 sq ft of ground-floor retail and 85 residential units above (mix: 20 studios, 40 one-bedrooms, 25 two-bedrooms). Market rents: studios $1,100/month, 1BR $1,450/month, 2BR $1,950/month, retail $28/sq ft NNN. Construction cost estimate: $165/sq ft for residential (net rentable), $185/sq ft for retail shell, $45/sq ft for structured parking (60 spaces), total site work and soft costs $2.1M. Land basis is $2.8M. Perform a full development feasibility: calculate total project cost, stabilized NOI (at 5% residential vacancy, 8% retail vacancy), development yield on cost, and value at a 5.5% stabilized cap rate. Determine whether there is sufficient development profit at a 15% minimum return-on-cost threshold, and identify the two assumptions that most heavily influence feasibility.","tags":["commercial","development","mixed-use","feasibility"],"author":"AINOW","created":"2024-02-15T11:50:00Z","featured":false},

    {"id":"re-24","title":"Hospitality Real Estate Underwriting","prompt":"You are a hospitality real estate analyst. Underwrite a 112-room limited-service hotel (select-service brand flag) in a suburban market near a mid-size airport. STR data shows competitive set RevPAR of $78.50. Property-level assumptions: occupancy 71%, ADR $112, physical RevPAR $79.52. Use the USALI format to project NOI: departmental revenues (rooms, F&B minimal, other), departmental expenses, undistributed expenses (administrative, marketing, franchise fees at 9% of room revenue, maintenance, utilities), fixed charges (insurance, taxes, FF&E reserve at 4% of total revenue, management fee at 3% of total revenue). The property is asking $9.8M. Calculate RevPAR, NOI, NOI margin, and going-in cap rate. Then model a brand conversion: the current operator switches to a higher-tier select-service flag, requiring $18,000/key in PIPs, projected to lift ADR by 12% and occupancy by 3 points over 18 months. Calculate the ROI on the PIP spend and revised cap rate on total investment.","tags":["commercial","hospitality","hotel","underwriting"],"author":"AINOW","created":"2024-02-15T11:55:00Z","featured":false},

    // --- RESIDENTIAL SALES (25-31) ---
    {"id":"re-25","title":"Buyer Representation: Negotiation Strategy","prompt":"You are a highly experienced buyer's agent. Your client has identified their target home: listed at $724,000, on the market for 23 days (originally listed at $749,000 with a $25,000 price reduction), in a market where the average days on market is 18 and sale-to-list ratio is 97.2%. The home had one previous offer that fell through at inspection due to a roof issue. The seller has already purchased their next home and is carrying two mortgages. Based on this intelligence, develop a complete offer strategy: (1) Recommend an initial offer price and the quantitative justification; (2) Draft the key contingency strategy — inspection, financing, appraisal — and explain which to include or waive and why; (3) Propose a escalation clause structure if appropriate; (4) Identify three non-price terms (closing date, leaseback, personal property) that can strengthen the offer without increasing price; (5) Prepare a counter-offer response strategy if the seller counters at $715,000. Write the actual offer letter narrative that explains the buyer's strength and intent.","tags":["residential","negotiation","buyer-agent","strategy"],"author":"AINOW","created":"2024-02-15T12:00:00Z","featured":false},

    {"id":"re-26","title":"Pre-Listing Home Preparation Plan","prompt":"You are a listing agent and certified home stager. A seller has a 2,400 sq ft, 1990s colonial that has been their primary residence for 18 years. It has original oak cabinets, brass fixtures, pink-tiled bathrooms, wall-to-wall carpet over hardwood, and a cluttered basement. Their budget for improvements before listing is $12,000. Create a prioritized pre-listing improvement plan that maximizes return on investment. For each recommendation: state the estimated cost, the likely impact on sale price or speed, and the ROI rationale. Cover: paint (interior and exterior), flooring (carpet removal), lighting fixture updates, bathroom cosmetics, landscaping and curb appeal, decluttering and storage, and professional staging. Identify the two improvements with the highest ROI and the two 'money pits' to avoid. Also write a 60-second verbal script the agent can use to present this plan to a skeptical seller who says 'buyers can update it themselves.'","tags":["residential","listing","staging","seller-prep"],"author":"AINOW","created":"2024-02-15T12:05:00Z","featured":false},

    {"id":"re-27","title":"Luxury Property Listing Description","prompt":"You are a luxury real estate copywriter. Write a compelling 350-word MLS listing description for a $2.2M contemporary home. The home features: 4,800 sq ft, 5 bedrooms, 4.5 baths, a chef's kitchen with Calacatta marble waterfall island and Wolf/Sub-Zero appliances, a 12-foot ceiling great room with floor-to-ceiling glass overlooking a private 1.1-acre wooded lot, a primary suite with spa bath and heated limestone floors, a 1,200-bottle wine cellar, a resort-style pool with spa and outdoor kitchen, and a 4-car garage with EV charging. The home is in a gated community 8 minutes from downtown and 15 minutes from the airport. Write the description in a voice that conveys lifestyle aspiration, not just specifications. Avoid clichés like 'stunning' and 'gorgeous.' The first sentence must be a scene-setter, not a spec list. Then write three social media caption variants (Instagram, Facebook, LinkedIn) for the same property, each with a different emotional hook.","tags":["residential","luxury","marketing","copywriting"],"author":"AINOW","created":"2024-02-15T12:10:00Z","featured":false},

    {"id":"re-28","title":"First-Time Buyer: Rent vs. Buy Analysis","prompt":"You are a financial advisor and real estate consultant. A 29-year-old professional in Denver, Colorado is deciding whether to buy a $520,000 condo or continue renting a comparable unit at $2,400/month. Buying scenario: 10% down ($52,000), 30-year mortgage at 6.85%, HOA $450/month, property taxes $4,680/year, insurance $1,200/year, maintenance 0.75% of value/year, PMI $195/month (until 20% equity), planned hold period 7 years, assumed appreciation 3.5%/year. Renting scenario: $2,400/month rent, 3% annual rent increases, renter's insurance $180/year, $52,000 down payment invested at 7% annual return. Perform a full 7-year rent vs. buy analysis including: total monthly cost of ownership vs. renting, opportunity cost of down payment, principal paydown, appreciation gains, tax deduction (assume 22% marginal rate), transaction costs at sale (6% commission + closing costs). Calculate the breakeven point where buying becomes financially superior to renting, and identify two non-financial factors that should weigh heavily in this decision.","tags":["residential","rent-vs-buy","first-time-buyer","financial-analysis"],"author":"AINOW","created":"2024-02-15T12:15:00Z","featured":false},

    {"id":"re-29","title":"Seller Pricing Strategy in a Shifting Market","prompt":"You are a listing agent in a market that has shifted from a strong seller's market to a more balanced market. Inventory is rising, days on market are increasing, and mortgage rates have pushed buyer affordability down 22% from the 2021 peak. A seller insists on listing at $689,000 based on their neighbor's 2022 sale price of $715,000. Current comparable closed sales over the past 60 days show a range of $642,000–$668,000. Prepare a complete pricing consultation. Include: (1) A data-driven market update showing the key metrics (active inventory, absorption rate, sale-to-list ratio, days on market trends over the past 18 months); (2) A 'cost of overpricing' calculation showing how a stale listing loses more money than an accurate initial price; (3) A pricing ladder — three strategic price points ($689K, $669K, $649K) with a probability-weighted outcome for net proceeds at each; (4) A script for handling the seller's objection: 'My neighbor got $715,000 two years ago.' Write the response in a way that is empathetic but firmly grounded in data.","tags":["residential","pricing","listing","seller-strategy"],"author":"AINOW","created":"2024-02-15T12:20:00Z","featured":false},

    {"id":"re-30","title":"Home Inspection Negotiation After Findings","prompt":"You are a buyer's agent. Your client's home inspection on a $485,000 single-family home revealed the following issues: (1) Roof has 3-5 years of remaining life, estimated replacement cost $14,500; (2) HVAC system is 18 years old and functional but near end of life, replacement cost $8,200; (3) Evidence of past moisture intrusion in the crawl space with current reading of elevated humidity (no active water); (4) Electrical panel is a Federal Pacific Stab-Lok, a known safety concern, replacement cost $3,800; (5) Minor items: cracked driveway ($800), missing GFCI outlets ($300), grading away from foundation needed ($600). The contract is at $485,000 and the sellers have received no other offers. Develop a complete post-inspection negotiation strategy: categorize items by severity and addressability, calculate the total remediation cost, and craft a specific request (combination of credits, repairs, and price reductions) that maximizes the buyer's position. Write the actual repair request letter in professional language. Then prepare a walkaway threshold analysis.","tags":["residential","inspection","negotiation","buyer-agent"],"author":"AINOW","created":"2024-02-15T12:25:00Z","featured":false},

    {"id":"re-31","title":"Listing Analysis and Pricing Report","prompt":"You are a listing agent preparing a comprehensive comparative market analysis. Review the subject property information and market data below, then produce a full CMA report: executive summary, 5-comparable analysis grid with adjustments, absorption rate analysis, recommended list price range with rationale, and a 30-day marketing timeline.\n\n[Paste the property details, financials, or listing description]","tags":["residential","cma","listing","pricing"],"author":"AINOW","created":"2024-02-15T12:30:00Z","featured":false},

    // --- PROPERTY MANAGEMENT (32-39) ---
    {"id":"re-32","title":"Tenant Screening Criteria Framework","prompt":"You are a property management attorney and operations director. Develop a comprehensive, legally compliant tenant screening criteria document for a 45-unit apartment portfolio in California. The criteria must be: (1) Objective and consistently applied to avoid fair housing violations — explain the protected classes under federal Fair Housing Act and California FEHA and how screening criteria can inadvertently create disparate impact; (2) Income verification — explain the appropriate income-to-rent ratio (typically 2.5-3x monthly rent), what income sources must be accepted under California law (Section 8 vouchers, etc.), and how to document verification; (3) Credit screening — what minimum score to set, how to handle thin files, and what adverse action notice requirements apply; (4) Rental history — what questions are permissible vs. prohibited when contacting previous landlords; (5) Criminal history — explain the California limitations on using criminal history and the DFEH guidance. Provide a sample decision matrix and the required adverse action letter template.","tags":["property-management","tenant-screening","legal","compliance"],"author":"AINOW","created":"2024-02-15T12:35:00Z","featured":false},

    {"id":"re-33","title":"Capital Improvement Budget Planning","prompt":"You are a property management director for a 200-unit class B apartment community built in 1988. The board has asked you to develop a 5-year capital expenditure plan. The property has the following deferred maintenance and lifecycle items coming due: roofs on 4 buildings (18,000 sq ft total, $9.50/sq ft), parking lot resurfacing (85,000 sq ft at $3.20/sq ft), domestic hot water heater replacement (6 units, $4,200 each), HVAC unit replacements (40 units at average $3,800 each, spread over 3 years), common area renovation ($120,000), elevator modernization (2 elevators, $65,000 each), and pool equipment/deck resurfacing ($38,000). Prioritize these items using a risk-based framework (life safety, code compliance, revenue impact, deferred cost multiplier). Create a year-by-year capital plan totaling all costs, identify financing options (reserves vs. capital call vs. bank line of credit), and calculate the impact on NOI and cap rate value for each year. Flag any items where deferral increases risk of catastrophic failure.","tags":["property-management","capital-expenditure","planning","multifamily"],"author":"AINOW","created":"2024-02-15T12:40:00Z","featured":false},

    {"id":"re-34","title":"Lease Renewal Retention Campaign","prompt":"You are a property management director. Your 120-unit apartment community has 38 leases expiring in the next 90 days and your portfolio average renewal rate is 58%, which is below the industry benchmark of 68%. Design a complete lease renewal retention campaign. Include: (1) A tiered renewal strategy — how to segment residents by renewal probability (high/medium/low) based on payment history, maintenance request frequency, and length of tenancy; (2) Renewal incentive matrix — at what rent increase threshold do residents typically leave, and what concessions (free month, carpet replacement, appliance upgrade) are cost-effective to offer vs. the cost of turnover ($2,800 average turn cost plus 21 days vacancy loss); (3) The renewal conversation script — how to approach the conversation 90, 60, and 30 days before expiration; (4) Communication templates for the initial renewal offer letter and two follow-up touchpoints; (5) How to handle a resident who asks for a rent reduction. Calculate the financial impact of increasing renewal rate from 58% to 68%.","tags":["property-management","retention","leasing","multifamily"],"author":"AINOW","created":"2024-02-15T12:45:00Z","featured":false},

    {"id":"re-35","title":"Preventive Maintenance Program Design","prompt":"You are a chief engineer and property operations consultant. Design a comprehensive preventive maintenance (PM) program for a 75-unit multifamily community. Structure the program into four time-based tiers: (1) Monthly PMs — unit HVAC filter changes, common area lighting inspections, fire extinguisher checks, stairwell and corridor inspections; (2) Quarterly PMs — HVAC coil cleaning, boiler inspection, exterior building inspection, parking lot inspection; (3) Semi-annual PMs — roof inspection and debris clearing, gutter cleaning, water heater flush, elevator service (if applicable), pest control perimeter treatment; (4) Annual PMs — full property inspection with report, fire alarm and sprinkler testing, backflow prevention testing, property insurance walk, window and caulk inspection. For each item, specify the skill level required (maintenance tech vs. licensed contractor), the estimated annual cost per item, and the consequence of deferral. Calculate the total annual PM budget and demonstrate the ROI versus reactive-only maintenance.","tags":["property-management","maintenance","operations","multifamily"],"author":"AINOW","created":"2024-02-15T12:50:00Z","featured":false},

    {"id":"re-36","title":"Eviction Process and Risk Management","prompt":"You are a property management attorney specializing in landlord-tenant law. Provide a comprehensive guide to the eviction process for a residential landlord in a state with standard landlord-tenant law (use Texas as the example). Structure the guide as follows: (1) Pre-eviction documentation — what records to maintain from day one of tenancy that will hold up in court; (2) Notice requirements — the different types of notices (pay or quit, cure or quit, unconditional quit), their required delivery methods, and timing; (3) Filing the eviction petition — where to file, fees, required documentation, and timeline; (4) The hearing — what to bring, how to present the case, and common mistakes landlords make that cause them to lose; (5) Writ of possession — the steps after a judgment and how to coordinate with the constable/sheriff; (6) Money judgment — how to collect unpaid rent after eviction. Include a checklist of the five most common landlord errors that allow tenants to delay or defeat evictions, and explain how to avoid them.","tags":["property-management","eviction","legal","landlord-tenant"],"author":"AINOW","created":"2024-02-15T12:55:00Z","featured":false},

    {"id":"re-37","title":"Property Management KPI Dashboard","prompt":"You are a property management analytics director. Design a comprehensive KPI dashboard for a regional property management company overseeing 800 units across 12 properties. Define and explain 20 key performance indicators across five categories: (1) Financial (NOI per unit, operating expense ratio, rent collection rate, delinquency rate, revenue per available unit); (2) Occupancy (physical occupancy rate, economic occupancy rate, average days to lease, renewal rate, net absorption); (3) Maintenance (work order completion time by priority tier, cost per work order, PM completion rate, emergency call rate per 100 units); (4) Resident Experience (renewal rate, review scores, complaint resolution time, move-out survey scores); (5) Team Performance (leasing conversion rate, maintenance cost per unit, turnover cost per unit). For each KPI, specify the formula, the industry benchmark, and the operational action that should be triggered when performance falls below the benchmark. Recommend a monthly reporting cadence and dashboard layout.","tags":["property-management","kpis","analytics","operations"],"author":"AINOW","created":"2024-02-15T13:00:00Z","featured":false},

    {"id":"re-38","title":"Commercial Property Management Transition","prompt":"You are a commercial property management consultant. A new owner has acquired a 65,000 sq ft office park (four buildings, 22 tenants) and needs to transition property management from the seller's in-house team to a third-party management firm within 60 days. Create a detailed transition plan and checklist covering: (1) Document collection — all leases, service contracts, warranties, permits, and financial records to obtain from the seller; (2) Tenant communication — the introduction letter, rent payment redirection notice, and how to conduct an initial tenant meeting to build trust; (3) Vendor/contractor transitions — which contracts to assume vs. rebid, and how to evaluate incumbent vendors; (4) Financial systems — setting up new bank accounts, establishing accounting codes, migrating to new property management software; (5) Physical inspection — 60-day inspection checklist for all common areas, mechanical systems, and individual tenant spaces; (6) Insurance transition — ensuring continuous coverage and updating certificates of insurance. Include a week-by-week timeline for the 60-day transition.","tags":["property-management","commercial","operations","transition"],"author":"AINOW","created":"2024-02-15T13:05:00Z","featured":false},

    {"id":"re-39","title":"Resident Problem Analysis and Resolution","prompt":"You are a property management consultant and mediator. Review the resident situation described below and recommend a resolution strategy. Include: root cause analysis, applicable lease provisions and legal considerations, a step-by-step resolution plan, communication templates for each touchpoint, and an escalation path if the initial resolution fails. Note any fair housing considerations that may apply.\n\n[Paste the property details, financials, or listing description]","tags":["property-management","resident-relations","legal","problem-solving"],"author":"AINOW","created":"2024-02-15T13:10:00Z","featured":false},

    // --- REAL ESTATE DEVELOPMENT (40-47) ---
    {"id":"re-40","title":"Entitlement Strategy for Residential Subdivision","prompt":"You are a land development consultant and entitlement specialist. A developer has acquired a 42-acre parcel on the edge of a growing suburb, currently zoned agricultural, with the intent to develop a 160-lot single-family residential subdivision with an average lot size of 8,500 sq ft (net of roads, open space, and infrastructure). The land cost is $2.1M. Walk through the complete entitlement process: (1) Pre-application steps — title review, ALTA survey, Phase I ESA, traffic study, geotechnical report, and community outreach; (2) Rezoning application — what to present to the planning commission, how to anticipate and address NIMBY opposition, and typical timeline (6-18 months); (3) Preliminary plat approval — the subdivision process, infrastructure requirements (roads, utilities, stormwater detention), and typical agency review cycle; (4) Final plat and construction drawings — engineer of record, civil plan submittal, public improvement bonds; (5) Financial modeling — total entitlement and infrastructure cost per lot, finished lot value vs. cost of carry, and the impact of an 18-month entitlement delay on project IRR.","tags":["development","entitlement","land","residential"],"author":"AINOW","created":"2024-02-15T13:15:00Z","featured":false},

    {"id":"re-41","title":"Construction Loan Structuring","prompt":"You are a real estate construction lender and developer. Explain how construction loans work to a developer pursuing their first ground-up multifamily project: a 72-unit apartment building with a total project cost of $18.4M (land $2.8M, hard costs $12.6M, soft costs $3.0M). Structure the explanation around: (1) Construction loan vs. permanent loan — why construction loans are short-term, interest-only, and floating rate; (2) Loan-to-cost (LTC) and loan-to-value (LTV) — how lenders size the loan (typically 65-70% LTC), what equity the developer must inject and when; (3) The draw schedule — how monthly draw requests work, the role of the lender's inspector, and what documentation is required for each draw; (4) Carry costs — calculate the interest cost on a $12.5M construction loan at SOFR + 300 bps (assume 7.8% all-in) over an 18-month construction period using an average outstanding balance of 65%; (5) Conversion to permanent financing — stabilization requirements (typically 90% occupancy for 90 days), DSCR requirements, and the mini-perm vs. agency loan decision.","tags":["development","construction-loan","finance","multifamily"],"author":"AINOW","created":"2024-02-15T13:20:00Z","featured":true},

    {"id":"re-42","title":"Proforma Development Model Review","prompt":"You are a real estate development underwriter at a private equity firm. Review the development proforma submitted below and provide a critical analysis. Identify: revenue assumption risks, cost underestimates (compare line items to market benchmarks), timeline optimism, financing assumptions, return metrics vs. risk profile, and the top three deal-killer issues. Then restate the proforma with conservative assumptions and calculate the revised return metrics.\n\n[Paste the property details, financials, or listing description]","tags":["development","proforma","underwriting","analysis"],"author":"AINOW","created":"2024-02-15T13:25:00Z","featured":false},

    {"id":"re-43","title":"Adaptive Reuse Feasibility: Office to Residential","prompt":"You are a development consultant specializing in adaptive reuse conversions. A developer is evaluating converting a 120,000 sq ft, 8-story 1970s office building in downtown Cleveland into 145 apartment units. The building was acquired for $3.2M at a distressed auction. The floor plate is 15,000 sq ft with a 120-foot depth from core to window. Analyze the conversion feasibility: (1) Physical assessment — explain why floor plate depth is the primary conversion constraint, how a 120-foot depth affects unit layouts and natural light, and what creative solutions (light wells, double-loaded corridors, hotel-style units) can mitigate the depth problem; (2) MEP systems — which mechanical, electrical, and plumbing systems typically must be gutted and replaced, and what cost premium this adds per sq ft vs. ground-up construction; (3) Financial modeling — assume $95/sq ft hard costs for the conversion, $22/sq ft soft costs, 18-month timeline; compare stabilized yield to a new construction project; (4) Tax incentives — explain federal and Ohio state historic tax credits and how they affect project economics; (5) Market — what apartment rents and absorption rates should be assumed for downtown Cleveland Class B product.","tags":["development","adaptive-reuse","office-conversion","feasibility"],"author":"AINOW","created":"2024-02-15T13:30:00Z","featured":false},

    {"id":"re-44","title":"Affordable Housing Development Finance","prompt":"You are an affordable housing finance specialist. Explain the Low Income Housing Tax Credit (LIHTC) program to a market-rate developer considering their first affordable project. Cover: (1) The two credit types — 9% competitive credits and 4% non-competitive credits with tax-exempt bonds — and when each is used; (2) How the credit is calculated — eligible basis, applicable fraction, credit percentage, and 10-year credit stream; (3) The equity syndication process — how syndicators package and sell LIHTC credits to corporate investors at approximately $0.90-$0.95/credit, and what equity pricing means for project feasibility; (4) Income and rent restrictions — AMI calculations, the 50% and 60% AMI rent restrictions, and long-term compliance period requirements (30 years extended use); (5) Layering other subsidies — HOME funds, CDBG, project-based Section 8, and state credits. Build a simplified financial model for a 60-unit LIHTC project showing sources and uses, the equity from tax credit syndication, and how the 9% credit can fill the gap between total project cost and available debt.","tags":["development","affordable-housing","lihtc","finance"],"author":"AINOW","created":"2024-02-15T13:35:00Z","featured":true},

    {"id":"re-45","title":"Green Building Certification Strategy","prompt":"You are a sustainable building consultant. A developer is planning a 200-unit multifamily project and wants to pursue LEED Gold certification. They need to understand the cost-benefit analysis before committing. Provide: (1) An overview of the LEED v4 BD+C: Multifamily rating system — the credit categories (Sustainable Sites, Water Efficiency, Energy & Atmosphere, Materials & Resources, Indoor Environmental Quality, Innovation) and the point thresholds for Certified, Silver, Gold, and Platinum; (2) The certification cost premium — hard cost premium for LEED Gold vs. a code-minimum building (typically 2-5%), soft costs for a LEED consultant and commissioning agent, and the registration/certification fees; (3) The financial benefits — utility cost savings (estimate 20-30% energy reduction), insurance premium discounts, green financing (Fannie Mae Green Rewards, lower cap rates from ESG-focused buyers), and potential density bonuses from local municipalities; (4) Alternative certifications — compare LEED to ENERGY STAR, Enterprise Green Communities, and Passive House in terms of cost, rigor, and market recognition; (5) Marketing value — how green certification affects lease-up velocity, rent premiums, and buyer exit pricing.","tags":["development","sustainability","leed","green-building"],"author":"AINOW","created":"2024-02-15T13:40:00Z","featured":false},

    {"id":"re-46","title":"Transit-Oriented Development Strategy","prompt":"You are a transit-oriented development (TOD) consultant. A regional transit authority has assembled land around three new light rail stations scheduled to open in 36 months and is seeking developer partners for mixed-use TOD projects. Each station is in a different context: Station A is in a downtown core (high-density zoning, $180/sq ft land value); Station B is in an established residential neighborhood (opposition likely, current R-2 zoning); Station C is in an underdeveloped industrial area (brownfield remediation needed, $25/sq ft land value). For each station area, develop a development strategy addressing: appropriate density and use mix, likely community opposition and mitigation strategies, infrastructure requirements and funding sources (TIF, federal transit grants, TIFIA), parking strategy (the debate over parking minimums at TOD), and the financial feasibility challenge at each location. Explain what research shows about the 'transit premium' — how proximity to rail affects residential and commercial property values — and what conditions are necessary for that premium to materialize.","tags":["development","transit-oriented","urban-planning","strategy"],"author":"AINOW","created":"2024-02-15T13:45:00Z","featured":false},

    {"id":"re-47","title":"Real Estate Development Partnership Structure","prompt":"You are a real estate attorney specializing in joint venture structuring. Two parties are forming a development JV: Party A (the developer/operator) contributes land worth $3.5M, development expertise, and ongoing project management; Party B (the capital partner) contributes $12M of equity capital required to complete a 90-unit condominium development with a total project cost of $22M. Advise on how to structure the JV. Cover: (1) LLC vs. limited partnership — the structural options and tax implications of each; (2) Capital contributions and deemed equity — how to credit the developer's land contribution as equity in the waterfall; (3) The preferred return — why capital partners typically require an 8-12% preferred return, how it accrues and compounds, and when it is paid; (4) The promote/carried interest — typical promote structures (50/50 split above preferred, two-tier promote with higher developer share above a second IRR hurdle); (5) Decision-making and control — what decisions require unanimous consent, major decision thresholds, and what happens in a deadlock; (6) Capital call provisions, dilution mechanics if a party cannot fund a capital call, and buy-sell ('shotgun') provisions.","tags":["development","joint-venture","legal","finance"],"author":"AINOW","created":"2024-02-15T13:50:00Z","featured":false},

    // --- LEASE NEGOTIATION (48-54) ---
    {"id":"re-48","title":"Office Lease Negotiation Playbook for Tenant","prompt":"You are a tenant representative specializing in corporate office leases. Your client, a 180-person professional services firm, is negotiating a 12,000 sq ft, 7-year office lease in a Class A building in Chicago's CBD. The landlord's initial proposal: $42/sq ft gross, $90/sq ft tenant improvement allowance, 3% annual escalations, 12 months free rent. Market context: Class A CBD asking rents average $41-$45/sq ft with a 14% vacancy rate; landlords are offering 15-18 months free rent and $100-$120/sq ft TI allowances to win long-term commitments. Develop a complete negotiation playbook: (1) The opening counter-proposal on rent, TI, free rent, and escalations with quantitative justification; (2) The five most valuable concessions to negotiate beyond rent (expansion options, contraction rights, sublease rights, rooftop access, naming rights); (3) Key lease clause negotiations — operating expense base year vs. expense stop, exclusion of capital expenditures from CAM, audit rights, casualty and condemnation provisions; (4) How to negotiate the personal guaranty — avoiding a full guaranty and alternatives (letter of credit, security deposit burn-down); (5) SNDA and estoppel certificate considerations.","tags":["leasing","office","tenant-rep","negotiation"],"author":"AINOW","created":"2024-02-15T13:55:00Z","featured":true},

    {"id":"re-49","title":"Retail Lease Key Clauses Deep Dive","prompt":"You are a retail tenant attorney. A small business owner is about to sign a 5-year retail lease for 2,200 sq ft in a lifestyle center and has asked you to explain the most critical lease clauses before they sign. Explain the following clauses in plain language, including what the landlord's standard language says, why it matters to the tenant, and what modification to request: (1) Percentage rent clause — base rent plus percentage of gross sales above a natural breakpoint; (2) Co-tenancy clause — rent reduction or termination right if an anchor tenant vacates; (3) Exclusivity clause — how to draft an effective exclusivity provision that actually protects the tenant's business; (4) Personal guarantee — scope, carve-outs, and alternatives; (5) Assignment and subletting — why the landlord's standard prohibition is onerous and what tenant-favorable language looks like; (6) Operating hours requirement — how mandatory hours can conflict with the tenant's business model; (7) CAM expense audit rights — why the right to audit CAM reconciliations is essential and what to look for in the audit. Provide sample 'tenant-friendly' language for each clause.","tags":["leasing","retail","legal","tenant-rights"],"author":"AINOW","created":"2024-02-15T14:00:00Z","featured":false},

    {"id":"re-50","title":"Industrial Lease Negotiation for Logistics Tenant","prompt":"You are a tenant representative specializing in industrial and logistics real estate. Your client is a third-party logistics company (3PL) seeking 180,000 sq ft of Class A distribution space in the Dallas-Fort Worth Metroplex for a 10-year term. Requirements: 36-foot clear height, 40 dock doors, 2 drive-in doors, 200-foot truck court depth, ESFR sprinkler system, and 4,000 amps of 277/480V power. The submarket has 4.2% vacancy with no speculative product delivering in the next 18 months. Develop the negotiation strategy given this tight supply environment: (1) How to identify build-to-suit vs. existing options and the economic tradeoffs; (2) The letter of intent (LOI) — what to lock in at the LOI stage before the landlord can shop the deal; (3) Key industrial lease provisions — base rent structure (NNN with how CAM is calculated), rent escalations (flat bumps vs. CPI), expansion rights, ROFO on adjacent expansion space; (4) How to negotiate tenant improvement allowance in an NNN lease for industrial (typically $8-12/sq ft); (5) Power sufficiency and landlord upgrade responsibility; (6) How to structure a renewal option at fair market rent with a floor and ceiling cap.","tags":["leasing","industrial","tenant-rep","logistics"],"author":"AINOW","created":"2024-02-15T14:05:00Z","featured":false},

    {"id":"re-51","title":"Ground Lease Fundamentals and Negotiation","prompt":"You are a real estate attorney specializing in ground leases. Explain ground lease structures to an investor considering selling the fee interest in their land to a ground lease investor while retaining a leasehold for development. Cover: (1) The basic structure — how a ground lease separates land ownership from improvements, typical terms (55-99 years), and how rent is set and reset; (2) Leasehold financing — how lenders evaluate and underwrite leasehold mortgage loans, the 'mortgageable ground lease' requirements (estoppel, non-disturbance, notice and cure rights for leasehold lender); (3) Rent reset mechanisms — fixed increases, CPI adjustments, fair market rent resets every 10-20 years — and how each affects the lessee's financial risk; (4) Reversion at expiration — what happens to the building at lease expiration, and how to negotiate for the lessee to have a purchase option or extended renewal rights; (5) Valuation — how ground leases are valued by investors (yield-on-land), typical cap rates for institutional ground leases (3.5-5%), and how the GLIDA (Ground Lease Investment & Distribution Association) standards affect pricing. Illustrate with a sample transaction where a developer sells a $4M parcel on a 99-year ground lease at a 4.5% cap rate.","tags":["leasing","ground-lease","legal","finance"],"author":"AINOW","created":"2024-02-15T14:10:00Z","featured":false},

    {"id":"re-52","title":"Lease Renewal vs. Relocation Analysis","prompt":"You are a tenant representative. Your client, a 65-person technology company, has a lease expiring in 14 months for 8,500 sq ft of Class B office space they are paying $28/sq ft gross. The landlord has offered a 5-year renewal at $31/sq ft with $45/sq ft TI. A competing building is offering 9,200 sq ft at $29.50/sq ft gross with $75/sq ft TI and 4 months free rent. Perform a complete stay-vs.-relocate financial analysis: (1) Calculate the net effective rent (NER) for both options after amortizing TI and free rent over the lease term; (2) Total occupancy cost comparison over the full 5-year term; (3) Relocation hard costs — moving expenses, new IT infrastructure, business disruption costs, and any required leasehold improvements above TI; (4) Soft/strategic considerations — proximity to clients, talent recruitment, brand/image, and employee commutes; (5) Negotiation leverage — how to use the competing offer to extract better terms from the incumbent landlord; (6) A final recommendation with a break-even analysis showing at what renewal rent and TI the incumbent building becomes economically equivalent to the competing offer.","tags":["leasing","office","tenant-rep","financial-analysis"],"author":"AINOW","created":"2024-02-15T14:15:00Z","featured":false},

    {"id":"re-53","title":"Lease Clause Review and Risk Assessment","prompt":"You are a commercial real estate attorney. Review the lease excerpt below and provide a detailed risk assessment for the tenant. Flag any provisions that are unusually landlord-favorable, explain the practical risk of each flagged clause, and recommend specific alternative language the tenant should request during negotiation.\n\n[Paste the property details, financials, or listing description]","tags":["leasing","legal","risk-assessment","tenant-rights"],"author":"AINOW","created":"2024-02-15T14:20:00Z","featured":false},

    {"id":"re-54","title":"Medical Office Lease Considerations","prompt":"You are a healthcare real estate specialist. A medical group is negotiating a 10-year lease for a 6,000 sq ft medical office suite that will require significant tenant improvements: $220,000 in MEP upgrades (increased power, medical gas rough-in, dedicated HVAC zones), $85,000 in plumbing (additional sinks, exam room plumbing), and $145,000 in interior build-out. The landlord is offering $70/sq ft TI allowance. Explain the unique lease considerations for medical tenants: (1) Why medical office TI costs are typically 2-3x conventional office, and how to negotiate an above-market TI allowance by demonstrating the creditworthiness and sticky nature of medical tenants; (2) HIPAA compliance and privacy considerations in the lease (exam room sound attenuation requirements, patient access); (3) Regulatory and licensing requirements — how zoning, health department approvals, and certificate of need regulations should be handled in the lease (landlord compliance obligations, delayed opening protections); (4) Signage and ADA requirements specific to medical facilities; (5) The 'medical office premium' — why medical office commands lower vacancy and higher rents than conventional office, and how to use this as leverage in negotiations.","tags":["leasing","medical-office","healthcare","negotiation"],"author":"AINOW","created":"2024-02-15T14:25:00Z","featured":false},

    // --- REAL ESTATE FINANCE (55-62) ---
    {"id":"re-55","title":"Commercial Mortgage Underwriting Standards","prompt":"You are a commercial real estate lender explaining underwriting standards to a borrower seeking their first commercial loan. The borrower wants to finance a $4.2M purchase of a 24-unit apartment building. Explain the five key underwriting metrics lenders evaluate: (1) Loan-to-Value (LTV) — how lenders determine value (appraisal vs. purchase price), typical maximum LTV by property type (75% for multifamily agency, 65-70% for commercial bank), and why LTV limits protect lenders; (2) Debt Service Coverage Ratio (DSCR) — the formula (NOI / Annual Debt Service), minimum thresholds by lender type (1.20x bank, 1.25x agency), and how lenders calculate 'underwritten NOI' vs. actual NOI (they haircut income and gross up expenses); (3) Debt Yield — why increasingly used in addition to DSCR, how it's calculated (NOI / Loan Amount), and typical minimums of 8-10%; (4) Borrower qualification — net worth, liquidity, credit score requirements, and experience requirements; (5) Global cash flow analysis — how lenders look at all of the borrower's income and debt obligations, not just the subject property. Calculate the maximum loan amount for the subject property assuming $268,000 stabilized NOI at 1.25x DSCR, 6.8% interest rate, 30-year amortization, and 75% LTV.","tags":["finance","commercial-mortgage","underwriting","lending"],"author":"AINOW","created":"2024-02-15T14:30:00Z","featured":true},

    {"id":"re-56","title":"Real Estate Capital Stack Explained","prompt":"You are a real estate capital markets advisor. Explain the real estate capital stack to a high-net-worth investor considering their first real estate private equity investment. Use a specific example: a $28M acquisition of a 200-unit apartment complex financed as follows — senior debt $18.2M (65% LTV), mezzanine debt $2.8M (10% of capital stack), preferred equity $2.2M, common equity $4.8M (split 80/20 LP/GP). Explain: (1) The risk/return profile and security position of each layer — who gets paid first, who absorbs losses first, and how this drives expected return (senior debt 6.5%, mezz debt 10-12%, preferred equity 12-15%, common equity 18%+ target IRR); (2) How mezzanine debt differs from preferred equity in terms of legal remedies (foreclosure on LLC interests vs. equity rights), return structure (fixed interest vs. preferred return), and lender vs. equity investor treatment; (3) The waterfall calculation — show the distribution order for a scenario where the property is sold for $32M after 5 years, with $18M debt remaining and $2.8M mezz paid off, and how each layer of the capital stack receives their proceeds; (4) When and why developers use each layer of the capital stack.","tags":["finance","capital-stack","investment","private-equity"],"author":"AINOW","created":"2024-02-15T14:35:00Z","featured":false},

    {"id":"re-57","title":"CMBS Loan vs. Bank Loan Analysis","prompt":"You are a real estate finance advisor. A borrower is refinancing a $7.5M stabilized retail center and has received two competing loan proposals: Proposal A — a CMBS (commercial mortgage-backed securities) conduit loan at 6.85% fixed, 10-year term, 30-year amortization, 65% LTV, full recourse for 12 months then non-recourse; Proposal B — a portfolio bank loan at 7.10% fixed, 5-year term (with rate reset), 25-year amortization, 70% LTV, full recourse. Compare these loans across eight dimensions: (1) Rate and cost (note rate, origination fee, exit fee, prepayment penalty — CMBS defeasance vs. bank yield maintenance); (2) Leverage and loan sizing; (3) Recourse and personal liability; (4) Flexibility — prepayment, assumption, and supplemental loan capabilities; (5) Cash management (CMBS cash sweeps vs. bank flexibility); (6) Escrow requirements; (7) Servicing and servicer relationship (master servicer, special servicer in CMBS vs. direct bank relationship); (8) Execution timeline and certainty. Make a final recommendation based on the borrower's likely need to sell or refinance within 7 years.","tags":["finance","cmbs","commercial-mortgage","debt"],"author":"AINOW","created":"2024-02-15T14:40:00Z","featured":false},

    {"id":"re-58","title":"Real Estate Private Equity Fund Structure","prompt":"You are a real estate private equity attorney and fund manager. Explain how a real estate private equity fund is structured to a family office considering a $5M commitment. Cover: (1) Fund structure — why most real estate PE funds are organized as Delaware limited partnerships or LLCs, the GP/LP relationship, and how the fund entity differs from individual deal SPEs; (2) Fee structure — the management fee (typically 1.5-2% of committed/invested capital), the carried interest/promote (20% above an 8% preferred return), and the fee offset provisions; (3) The investment period and fund life — typical 2-3 year investment period, 5-7 year hold period, 1-2 year wind-down; (4) Capital calls and distributions — how and when the GP can call committed capital, how distributions flow through the waterfall, and clawback provisions; (5) Fund documentation — the limited partnership agreement, subscription agreement, PPM; (6) The manager's track record and attribution analysis — how to evaluate whether a GP's historical returns are attributable to skill or market timing (alpha vs. beta). Describe three red flags in a fund PPM that would give you pause as a sophisticated investor.","tags":["finance","private-equity","fund-structure","investment"],"author":"AINOW","created":"2024-02-15T14:45:00Z","featured":false},

    {"id":"re-59","title":"Mortgage Rate Strategy for Investment Property","prompt":"You are a mortgage advisor specializing in investment property financing. An investor is acquiring a $650,000 rental property and is evaluating three financing options: Option A — 30-year fixed at 7.25%, 25% down; Option B — 15-year fixed at 6.625%, 25% down; Option C — 7/1 ARM at 6.375%, 25% down (rate adjusts annually after year 7 with a 2% annual cap and 5% lifetime cap). Assuming the property rents for $3,800/month, operating expenses of $980/month (excluding debt service), and a planned hold period of 8 years, perform a comprehensive comparison. Calculate for each option: monthly payment, monthly cash flow, DSCR, cash-on-cash return, total interest paid over 8 years, equity accumulated in year 8 (assuming 3% annual appreciation), and total wealth created. Then analyze the interest rate risk of the ARM in Year 8 — calculate the payment impact if the rate hits the lifetime cap. Recommend the optimal strategy for an investor who values predictability vs. one who optimizes for cash flow.","tags":["finance","mortgage","investment-property","strategy"],"author":"AINOW","created":"2024-02-15T14:50:00Z","featured":false},

    {"id":"re-60","title":"Real Estate Tax Strategy for Portfolio Investors","prompt":"You are a CPA specializing in real estate taxation. A real estate investor has a portfolio generating $180,000/year in gross rental income across four properties (two single-family, one 8-unit, one commercial). They have $85,000 in depreciation deductions, $62,000 in mortgage interest, $28,000 in operating expenses, and are asking how to legally minimize their tax liability. Provide a comprehensive real estate tax strategy covering: (1) The passive activity rules — the $25,000 rental loss allowance phase-out for taxpayers earning $100K-$150K, and when the investor qualifies as a 'real estate professional' to unlock unlimited passive loss deductions; (2) Cost segregation — how a cost segregation study on the 8-unit building can accelerate $85,000 of depreciation into Years 1-5, the cost of a study ($4,000-$8,000), and the first-year tax benefit; (3) Bonus depreciation — the current status of 100% bonus depreciation phase-down and strategies to maximize it; (4) The QBI deduction for rental income under Section 199A and the requirements to qualify; (5) Entity structuring — LLC vs. S-Corp vs. C-Corp for holding rental property and the self-employment tax implications of each.","tags":["finance","tax","portfolio","strategy"],"author":"AINOW","created":"2024-02-15T14:55:00Z","featured":false},

    {"id":"re-61","title":"Deal Financing Structure Analysis","prompt":"You are a real estate finance advisor. Review the proposed acquisition or development deal details below and provide a comprehensive financing strategy. Analyze: optimal loan type and lender category, maximum leverage achievable, estimated debt service and DSCR, equity requirement, alternative capital sources, and key financing risks given the current interest rate environment.\n\n[Paste the property details, financials, or listing description]","tags":["finance","deal-structuring","debt","analysis"],"author":"AINOW","created":"2024-02-15T15:00:00Z","featured":false},

    {"id":"re-62","title":"Agency Lending: Fannie Mae vs. Freddie Mac","prompt":"You are a multifamily debt broker. A borrower owns a 54-unit stabilized apartment community and is evaluating agency loan options for a 10-year refinance. Compare Fannie Mae and Freddie Mac multifamily loan programs across the following dimensions: (1) Loan programs — Fannie DUS vs. Freddie Optigo, small balance programs (Fannie SBL vs. Freddie SBL), and when each is preferred; (2) Underwriting differences — how each agency underwrites to DSCR and debt yield, differences in expense underwriting methodology, and occupancy requirements; (3) Pricing — how spreads to benchmark rates differ between agencies, what drives spread differences at any given time, and how to play the agencies against each other for best execution; (4) Non-recourse carve-outs — what 'bad boy' provisions are standard and how they differ; (5) Supplemental loan availability — how to access additional proceeds after 12 months of seasoning without refinancing the first mortgage; (6) Green financing — Fannie Mae Green Rewards and Freddie Mac Green Advantage programs, energy audit requirements, and the pricing benefit for qualifying properties. Explain the rate-lock options (early rate lock, forward rate lock) and when each is appropriate.","tags":["finance","agency-lending","multifamily","fannie-freddie"],"author":"AINOW","created":"2024-02-15T15:05:00Z","featured":false},

    // --- MARKET ANALYSIS (63-69) ---
    {"id":"re-63","title":"Submarket Selection Framework for Multifamily Investment","prompt":"You are a real estate market research analyst. Develop a systematic framework for evaluating and ranking metropolitan submarkets for multifamily investment. The framework should be quantitative and reproducible. Define and explain the data sources and weighting for six categories of analysis: (1) Demand drivers — population growth rate (Census, ESRI), household formation trends, net migration (IRS migration data), employment growth by sector; (2) Supply analysis — units under construction as a percentage of existing stock, deliveries over the next 24 months, historical absorption rate; (3) Rent growth — trailing 12-month effective rent growth, rent-to-income ratios by income tier, rental vs. homeownership affordability spread; (4) Economic base quality — employment diversification (HHI score), wage growth, major employer concentration risk, university or government anchor stability; (5) Landlord-tenant regulatory environment — eviction law restrictiveness, rent control risk index, permitting speed; (6) Liquidity — transaction volume, cap rate compression/expansion trend, buyer depth. Apply this framework to compare three specific markets (Austin TX, Columbus OH, and Charlotte NC) and provide a ranked investment recommendation with quantitative justification.","tags":["market-analysis","multifamily","submarket","research"],"author":"AINOW","created":"2024-02-15T15:10:00Z","featured":false},

    {"id":"re-64","title":"Real Estate Cycle Positioning Strategy","prompt":"You are a real estate economist and portfolio strategist. Explain the four phases of the real estate cycle (Recovery, Expansion, Hypersupply, Recession) using the Mueller/Pyhrr framework. For each phase: identify the key market indicators that signal the phase (vacancy rate direction, construction starts, rent growth, cap rate direction, transaction volume), explain the optimal investment strategy (buy/hold/sell/develop), and describe which property types and market tiers tend to enter and exit each phase first. Then assess where the current market (2024-2025) appears to be in the cycle for each major property type (multifamily, industrial, office, retail, hotel) and explain why different asset classes are at different points in the cycle simultaneously. Conclude with three specific actionable investment strategies appropriate for the current cycle position — one opportunistic, one value-add, and one core/defensive.","tags":["market-analysis","real-estate-cycle","strategy","economics"],"author":"AINOW","created":"2024-02-15T15:15:00Z","featured":true},

    {"id":"re-65","title":"Competitive Market Analysis for New Development","prompt":"You are a market research consultant. A developer is planning a 220-unit luxury apartment project in a specific submarket and needs a competitive analysis before finalizing the unit mix and rent assumptions. Design a methodology for conducting a comprehensive competitive market study: (1) Define the competitive set — how to identify direct competitors (Class A, 150+ units, delivered in the past 10 years, within a 3-mile radius) and why to also include pipeline projects as future competition; (2) Data collection protocol — what to document for each comp (unit mix, square footage, amenity package, parking ratio, concession level, effective rent per sq ft, occupancy); (3) Absorption analysis — how to calculate projected absorption for the new project based on historical stabilization velocity of comparable lease-ups; (4) Unit mix optimization — using the competitive data to identify underserved unit types and size sweet spots; (5) Amenity gap analysis — which amenity features differentiate the best-performing projects; (6) Rent modeling — how to build a competitive positioning matrix and set asking rents that achieve a target occupancy within 18 months. Include a sensitivity table showing stabilization timing at different rent levels.","tags":["market-analysis","development","multifamily","research"],"author":"AINOW","created":"2024-02-15T15:20:00Z","featured":false},

    {"id":"re-66","title":"Commercial Real Estate Market Report","prompt":"You are a commercial real estate market analyst at a major brokerage. Review the market data and property information provided below and produce a professional market report. Include: market overview and key trends, supply and demand metrics, rent and vacancy analysis, investment activity summary, notable transactions, and a 12-month outlook with specific implications for investors, tenants, and developers.\n\n[Paste the property details, financials, or listing description]","tags":["market-analysis","commercial","reporting","research"],"author":"AINOW","created":"2024-02-15T15:25:00Z","featured":false},

    {"id":"re-67","title":"Demographic Analysis for Retail Site Selection","prompt":"You are a retail real estate site selection consultant. A fast-casual restaurant chain is evaluating three potential sites in a metro area and has asked you to perform a demographic analysis to rank them. Explain the methodology for a comprehensive trade area analysis: (1) Define the primary, secondary, and tertiary trade areas using drive-time analysis (5, 10, 15 minutes) rather than radius rings — explain why drive-time is more accurate; (2) Key demographic metrics to analyze — daytime population vs. residential population, household income distribution, age cohort distribution (the chain targets millennials/Gen Z), population density, and traffic count data (AADT); (3) Psychographic profiling — explain how ESRI Tapestry or Nielsen PRIZM segmentation can identify lifestyle compatibility beyond raw demographics; (4) Void analysis — how to identify where the chain is underrepresented relative to the demographic opportunity; (5) Cannibalization analysis — minimum distance requirements between locations and how to model same-store sales impact from a new opening; (6) Co-tenancy synergies — what anchor tenants and neighbors drive the highest capture rates for the chain's customer profile. Apply this framework to evaluate the three hypothetical sites.","tags":["market-analysis","retail","site-selection","demographics"],"author":"AINOW","created":"2024-02-15T15:30:00Z","featured":false},

    {"id":"re-68","title":"Real Estate Market Forecasting Methods","prompt":"You are a real estate economist. Explain the four primary methodologies used to forecast real estate market performance to a pension fund investment committee considering a $200M allocation to real estate: (1) Econometric modeling — how regression models link macroeconomic variables (GDP growth, employment, interest rates, demographic shifts) to real estate performance metrics (vacancy, rent growth, cap rates); the strengths and weaknesses of backward-looking models; (2) Supply-demand analysis — how to model net absorption, deliveries, and vacancy projections from the bottom up; why supply forecasting is inherently uncertain (permitting to delivery timeline variability); (3) Capital flows analysis — how NCREIF, MSCI/IPD, and transaction data reveal investor sentiment, and why capital flows can cause valuations to diverge from fundamental value; (4) Expert survey/consensus methods — CBRE, JLL, and CoStar forecasts; how to weight conflicting expert views and account for systematic optimism bias in sell-side research. Explain how to use multiple methods to build a range of outcomes (base case, bull, bear) and how to stress-test return assumptions against historical downturns (2001, 2008-2010, 2020).","tags":["market-analysis","forecasting","economics","research"],"author":"AINOW","created":"2024-02-15T15:35:00Z","featured":false},

    {"id":"re-69","title":"Highest and Best Use Analysis","prompt":"You are a commercial appraiser and development consultant. Perform a highest and best use (HBU) analysis for a 1.8-acre corner parcel at a major arterial intersection in a growing Sun Belt suburb. The parcel is currently improved with a 6,000 sq ft single-story office building built in 1975, generating $84,000/year in rent from a month-to-month tenant. The land value is estimated at $2.8M as vacant. The office building contributes $0 in additional value (the improvement has no contributory value). The site can be developed under current zoning to: (A) a 15,000 sq ft strip retail center; (B) a 3-story, 45,000 sq ft mixed-use building (ground-floor retail + office); (C) a fast-food pad site (ground lease at $180,000/year NNN); (D) continue the existing office use. For each use: estimate development cost, stabilized value, residual land value, and developer profit. Apply the four tests of HBU (physically possible, legally permissible, financially feasible, maximally productive) to each use. Conclude with the HBU determination and the optimal disposition strategy for the current owner.","tags":["valuation","highest-best-use","development","commercial"],"author":"AINOW","created":"2024-02-15T15:40:00Z","featured":false},

    // --- PROPERTY MARKETING (70-74) ---
    {"id":"re-70","title":"Investment Property Marketing Package","prompt":"You are a commercial real estate investment sales broker. Create a comprehensive offering memorandum (OM) outline for a 32-unit multifamily property being offered at $5.1M. The OM must be structured to appeal to private capital buyers, family offices, and 1031 exchange buyers. Define the exact sections, the data to include in each section, and the narrative approach for: (1) Executive summary — the investment thesis in 150 words that leads with the opportunity, not the property description; (2) Investment highlights — five bullet points that quantify the opportunity (yield, value-add upside, market fundamentals); (3) Property description — physical details, unit mix, recent capital improvements, and amenities; (4) Location analysis — market overview, submarket fundamentals, proximity to demand drivers; (5) Financial analysis — rent roll, T-12 operating statement, proforma, debt assumptions, return metrics; (6) Market comparables — rent comps and sales comps with source citations; (7) Photographs and aerial maps. Explain what makes an OM compelling vs. generic, and write the executive summary for the sample property (located in suburban Atlanta, 1998 vintage, 94% occupied, $245/unit/month below-market rents).","tags":["marketing","commercial","multifamily","offering-memorandum"],"author":"AINOW","created":"2024-02-15T15:45:00Z","featured":false},

    {"id":"re-71","title":"Digital Marketing Strategy for Real Estate Agent","prompt":"You are a real estate marketing consultant. Design a comprehensive 90-day digital marketing strategy for a residential real estate agent in a competitive market who has a $1,500/month marketing budget. The strategy should cover: (1) SEO and local search — how to optimize a Google Business Profile, build neighborhood-specific content pages, and rank for 'best real estate agent in [city]' searches; (2) Social media content calendar — a 4-week repeating content framework for Instagram and Facebook with post types (market updates, listings, behind-the-scenes, client stories, local business features), optimal posting frequency, and how to create Reels with no video production experience; (3) Email marketing — a segmented list strategy (past clients, active buyers, active sellers, sphere of influence), monthly newsletter template, and automated drip campaigns for buyer and seller leads; (4) Paid advertising — a $500/month Meta ads framework targeting demographics most likely to buy or sell in the agent's zip codes; (5) Video — why one 'neighborhood tour' video per month is the single highest-ROI content investment. Include a 90-day KPI framework with realistic expectations for each channel.","tags":["marketing","residential","digital-marketing","agent"],"author":"AINOW","created":"2024-02-15T15:50:00Z","featured":false},

    {"id":"re-72","title":"New Development Lease-Up Marketing Plan","prompt":"You are a multifamily marketing director. A new 180-unit luxury apartment community is 6 months from delivering its first units and needs a pre-leasing and lease-up marketing strategy targeting 90% occupancy within 6 months of first move-ins. The property is in a market with 3 competing new deliveries in the same submarket within the same 12-month window. Develop a complete marketing plan: (1) Brand identity — how to differentiate the property with a distinct brand story beyond 'luxury'; (2) Pre-leasing strategy — when to open the leasing office (typically 90-120 days before delivery), what to offer for pre-leasing commitments (first-month specials, unit selection priority), and how to build a waitlist; (3) Digital marketing infrastructure — website requirements, ILS presence (Apartments.com, Zillow, Rent.com), SEO targeting, Google Ads budget and keyword strategy; (4) Concession strategy — the math behind offering 1-2 months free rent vs. a permanent rent reduction, and how to avoid setting a new market rent floor that hurts future renewals; (5) Referral and grassroots marketing — corporate outreach program, local employer partnerships, broker referral program; (6) A week-by-week leasing velocity target to reach stabilization.","tags":["marketing","multifamily","lease-up","development"],"author":"AINOW","created":"2024-02-15T15:55:00Z","featured":false},

    {"id":"re-73","title":"Commercial Property Repositioning Marketing Strategy","prompt":"You are a commercial real estate marketing strategist. A landlord has completed a $3.2M renovation of a dated 1980s suburban office park, upgrading common areas, adding a fitness center and conference facility, improving the facade, and rebranding the property. The current occupancy is 62% and the goal is to reach 88% occupancy within 18 months. Develop a comprehensive repositioning marketing strategy: (1) New brand narrative — how to tell the repositioning story to the brokerage community and prospective tenants; (2) Broker engagement — why broker relationships drive 70%+ of commercial leasing decisions, how to host a broker event, and what materials to provide (offering flyer, virtual tour, floor plan options); (3) Direct tenant marketing — how to identify and target tenants in the submarket whose leases are expiring in 12-24 months using CoStar or real estate intelligence platforms; (4) Digital presence — property website requirements, LinkedIn advertising targeting CFOs and office managers in the target company size range, and Google search ads for '[city] office space for lease'; (5) Prospect pipeline management — deal tracking, follow-up cadence, and how to convert tours to proposals to executed LOIs.","tags":["marketing","commercial","office","repositioning"],"author":"AINOW","created":"2024-02-15T16:00:00Z","featured":false},

    {"id":"re-74","title":"Property Listing Marketing Copy Review","prompt":"You are a real estate marketing copywriter and listing strategy advisor. Review the property description and marketing materials below. Identify weaknesses in the current copy (clichés, missing emotional hooks, spec-list syndrome, weak headline), then rewrite the listing description, create three social media captions for different platforms, and suggest five listing photos or video shots that would strengthen the marketing.\n\n[Paste the property details, financials, or listing description]","tags":["marketing","copywriting","listing","residential"],"author":"AINOW","created":"2024-02-15T16:05:00Z","featured":false},

    // --- REITs (75-79) ---
    {"id":"re-75","title":"REIT Sector Analysis and Investment Thesis","prompt":"You are a REIT equity analyst. Build a comparative investment thesis across four REIT sectors for an institutional investor seeking $50M in REIT exposure: (1) Residential REITs (apartment REITs like Equity Residential, AvalonBay) — analyze the supply/demand fundamentals in coastal vs. Sun Belt markets, same-store NOI growth trends, and how rising homeownership costs create a structural tailwind; (2) Industrial REITs (Prologis, Rexford) — evaluate e-commerce penetration, rent mark-to-market opportunity on below-market leases, development platform value, and cap rate sensitivity; (3) Healthcare REITs (Welltower, Ventas) — explain the three healthcare sub-sectors (senior housing operating portfolio, NNN medical office, skilled nursing) and their different risk profiles, the demographic tailwind from aging Baby Boomers, and SHOP vs. NNN lease structure risk; (4) Net Lease REITs (Realty Income, STORE Capital) — explain AFFO yield, dividend sustainability analysis, tenant credit diversification, and interest rate sensitivity. For each sector, provide a relative valuation assessment using P/AFFO multiples, dividend yield, and NAV discount/premium, and make a ranked allocation recommendation.","tags":["reit","investment","equity-analysis","sectors"],"author":"AINOW","created":"2024-02-15T16:10:00Z","featured":true},

    {"id":"re-76","title":"REIT vs. Direct Real Estate Investment Comparison","prompt":"You are a wealth advisor and real estate investment consultant. A high-net-worth investor with $500,000 to allocate to real estate is weighing three options: (A) buying a direct rental property; (B) investing in publicly traded REITs; (C) investing in a non-traded REIT or private real estate fund. Compare all three options across eight dimensions: (1) Liquidity — daily liquidity for public REITs vs. 7-10 year lock-up for private funds vs. 30-60 day sell process for direct property; (2) Diversification — single asset concentration risk vs. portfolio diversification; (3) Control — direct ownership decision-making vs. passive capital; (4) Leverage — how each structure uses debt and how it amplifies both returns and risk; (5) Tax treatment — REIT dividends taxed as ordinary income vs. direct real estate depreciation benefits and capital gains treatment; (6) Minimum investment and accessibility; (7) Management burden — time commitment and expertise required; (8) Historical risk-adjusted returns — compare NCREIF NFI-ODCE (private real estate), FTSE NAREIT All REITs Index, and typical direct investor returns over 20-year periods. Recommend the optimal allocation mix for an investor in the 37% tax bracket who values income over growth.","tags":["reit","investment","direct-real-estate","comparison"],"author":"AINOW","created":"2024-02-15T16:15:00Z","featured":false},

    {"id":"re-77","title":"REIT Financial Statement Analysis","prompt":"You are a REIT equity analyst. Explain how to analyze a REIT's financial statements to a sophisticated investor new to REIT investing. The investor is looking at a midsize apartment REIT's 10-K. Explain: (1) Why GAAP net income is misleading for REITs — depreciation creates a GAAP loss that does not reflect economic reality, and why FFO (Funds From Operations) was developed by NAREIT as the industry standard earnings metric; (2) FFO vs. AFFO — the AFFO adjustment for recurring capex (unit renovations, carpet, appliances), straight-line rent adjustments, and debt issuance cost amortization; (3) Same-store NOI growth — why same-store analysis excludes acquisitions and dispositions and is the most important organic growth metric; (4) Balance sheet analysis — Net Debt to EBITDA ratio (typically 5-7x for investment grade REITs), fixed charge coverage ratio, debt maturity schedule and refinancing risk; (5) NAV per share calculation — how to estimate NAV by capitalizing segment NOI at market cap rates and compare to share price to assess premium or discount; (6) Payout ratio analysis — AFFO payout ratio and dividend sustainability. Walk through a sample calculation using simplified financial statements.","tags":["reit","financial-analysis","accounting","equity-research"],"author":"AINOW","created":"2024-02-15T16:20:00Z","featured":false},

    {"id":"re-78","title":"Mortgage REIT Analysis","prompt":"You are a fixed income and real estate analyst. Explain mortgage REITs (mREITs) to an investor who understands equity REITs but has never invested in mortgage REITs. Cover: (1) The fundamental business model — how mREITs use short-term borrowing (repo agreements, FHLB advances) to fund long-term mortgage assets (agency MBS, non-agency MBS, commercial mortgage loans), and how net interest income drives earnings; (2) The two main types — agency mREITs (invest in government-guaranteed MBS: Annaly Capital, AGNC) vs. hybrid/non-agency mREITs (Ladder Capital, Arbor Realty) and their different risk profiles; (3) Leverage and book value risk — why mREITs use 6-10x leverage and how interest rate movements (duration mismatch), credit spread widening, and margin calls can rapidly destroy book value; (4) Hedging — how mREITs use interest rate swaps, swaptions, and TBA forward sales to hedge duration risk, and why hedging is imperfect; (5) Dividend sustainability analysis — how to assess whether a high dividend yield (often 10-14%) is sustainable by analyzing earnings-to-dividend coverage ratio and book value trend; (6) Historical performance during rate cycles — how agency mREITs performed during the 2013 taper tantrum, 2018 rate rises, and 2022 rapid rate increase.","tags":["reit","mortgage-reit","fixed-income","analysis"],"author":"AINOW","created":"2024-02-15T16:25:00Z","featured":false},

    {"id":"re-79","title":"REIT Portfolio Construction for Income Investors","prompt":"You are a portfolio manager and income-focused investment advisor. Build a $250,000 REIT portfolio for a 65-year-old retiree seeking: 4.5-5.5% current dividend yield, dividend growth of at least 3% annually, low volatility relative to the REIT index, and meaningful diversification across property sectors. The investor has $75,000 in an IRA and $175,000 in a taxable account. Recommend specific REIT allocations by sector (use sector targets, not specific tickers), explain the tax placement strategy (which types of REITs to hold in IRA vs. taxable account given dividend tax treatment), construct a target portfolio with sector weightings and yield targets, and explain the portfolio rebalancing strategy. Then stress-test the portfolio: how does it perform in a 200 bps rate increase scenario (impact on REIT pricing and dividend coverage), a recession scenario (which sectors cut dividends), and an inflationary scenario (which sectors offer the best inflation hedge through rent escalations). Conclude with the three metrics the investor should monitor quarterly to assess portfolio health.","tags":["reit","portfolio","income-investing","retirement"],"author":"AINOW","created":"2024-02-15T16:30:00Z","featured":false},

    // --- REAL ESTATE TECHNOLOGY (80-83) ---
    {"id":"re-80","title":"PropTech Landscape and Investment Opportunities","prompt":"You are a venture capital analyst specializing in PropTech (property technology). Map the current PropTech landscape for a real estate operator considering technology investments to improve their portfolio operations and a VC considering PropTech fund investments. Organize the landscape into six categories: (1) Transaction technology — iBuyer platforms, digital closing/title (Blend, Doma), electronic earnest money, and AI-powered offer analysis; (2) Property management software — enterprise platforms (Yardi, RealPage, MRI) vs. newer challengers (AppFolio, Buildium, DoorLoop) and their respective strengths for different portfolio sizes; (3) Construction technology — BIM software, construction project management (Procore, Buildertrend), cost estimation AI, and modular/prefab innovations; (4) Leasing and marketing — AI-powered chatbots, virtual tours (Matterport), self-showing technology, and revenue management systems (LRO, Yieldstar); (5) IoT and smart building — smart access control, predictive maintenance sensors, energy management systems, and tenant experience apps; (6) Real estate data and analytics — CoStar vs. challengers, alternative data (satellite imagery, foot traffic, credit card spend). For each category, identify the market leader, one emerging challenger, and the adoption barrier that is slowing industry-wide deployment.","tags":["technology","proptech","innovation","operations"],"author":"AINOW","created":"2024-02-15T16:35:00Z","featured":false},

    {"id":"re-81","title":"AI Implementation in Property Management","prompt":"You are a real estate technology consultant and property management operations director. Develop a practical AI implementation roadmap for a regional property management company managing 2,500 units across 18 properties. Prioritize AI use cases by impact and implementation complexity in three horizons: (1) Quick wins (0-6 months, minimal IT infrastructure change) — AI maintenance request triage (classifying and routing work orders by priority using natural language processing), AI-powered leasing chatbots that answer prospect inquiries 24/7, and automated delinquency communications that personalize messaging based on payment history; (2) Medium-term (6-18 months) — predictive maintenance models that identify equipment failure risk from IoT sensor data, AI-driven rent optimization that recommends lease renewal pricing based on market data and resident profile, and automated lease abstraction for portfolio compliance monitoring; (3) Transformational (18-36 months) — dynamic pricing for short-term units, AI-powered property acquisition underwriting that integrates market data with the company's portfolio data, and natural language lease negotiation assistance. For each use case: describe the data requirements, the realistic productivity gain, the estimated implementation cost, and the key vendor options. Address change management and staff training requirements.","tags":["technology","ai","property-management","operations"],"author":"AINOW","created":"2024-02-15T16:40:00Z","featured":false},

    {"id":"re-82","title":"Blockchain and Smart Contracts in Real Estate","prompt":"You are a legal technology consultant and real estate attorney. Explain the current and near-future applications of blockchain technology and smart contracts in real estate transactions to a skeptical industry veteran. Cover: (1) The fundamental problem blockchain solves — fragmented, paper-based title records, slow and opaque escrow/closing processes, and illiquid fractional ownership; (2) Tokenization of real estate assets — how a property can be divided into digital tokens representing fractional ownership interests, how token holders receive pro-rata income and appreciation, SEC regulatory treatment under the Howey test, and existing platforms (RealT, tZERO, Republic Real Estate); (3) Smart contract escrow — how smart contracts can automate the release of earnest money, title insurance, and closing funds upon verified conditions (title clearance, inspection contingency waiver, lender funding), reducing closing timelines from 30-45 days to potentially 5-7 days; (4) Current obstacles — why blockchain real estate is still nascent (state recording statute reform required, title insurance industry resistance, lender adoption, consumer education); (5) A realistic 10-year adoption timeline. Separate genuine innovation from hype and identify the two use cases most likely to achieve mainstream adoption first.","tags":["technology","blockchain","legal","innovation"],"author":"AINOW","created":"2024-02-15T16:45:00Z","featured":false},

    {"id":"re-83","title":"Virtual Tour and Digital Marketing Technology Stack","prompt":"You are a real estate marketing technology consultant. Design the optimal technology stack for a mid-size residential brokerage (45 agents, 200+ transactions/year) that wants to lead its market in digital marketing and virtual property presentation. Evaluate and recommend tools in each category: (1) 3D virtual tours — compare Matterport, iGUIDE, and Zillow 3D Home on cost per scan, camera hardware required, output quality, and integration with MLS platforms; (2) Video production — drone photography vendors and FAA Part 107 requirements, gimbal stabilization, and editing software recommendations for agents without video backgrounds; (3) CRM and lead management — evaluate Follow Up Boss, LionDesk, and Sierra Interactive for lead routing, automated follow-up sequences, and team management features; (4) Transaction management — Dotloop vs. Skyslope vs. DocuSign Rooms for compliance, e-signature, and audit trail; (5) Social media scheduling — Later vs. Hootsuite vs. Sprout Social for a small team managing multiple agent accounts; (6) Website platform — AgentFire vs. Luxury Presence vs. Sierra Interactive for IDX integration, lead capture, and SEO performance. Provide a total monthly cost estimate for the complete stack and identify the single highest-ROI technology investment if the budget is limited.","tags":["technology","marketing","digital","brokerage"],"author":"AINOW","created":"2024-02-15T16:50:00Z","featured":false},

    // --- AFFORDABLE HOUSING (84-87) ---
    {"id":"re-84","title":"Affordable Housing Needs Assessment","prompt":"You are an affordable housing policy consultant and real estate developer. Conduct a comprehensive affordable housing needs assessment framework for a mid-size city of 285,000 residents. Structure the assessment around: (1) Demand quantification — how to calculate housing cost burden (households paying 30%+ of income on housing), severe cost burden (50%+), and the housing affordability gap by income tier (0-30% AMI, 31-50% AMI, 51-80% AMI, 81-120% AMI); (2) Supply analysis — the current inventory of deed-restricted affordable units by bedroom count, the LIHTC and Section 8 inventory expiring over the next 15 years ('expiring use' crisis), and naturally occurring affordable housing (NOAH) at risk of market-rate conversion; (3) Gap calculation — the number of affordable units needed at each income tier to achieve a target housing cost burden rate of 25%; (4) Barriers to production — land costs, construction costs, NIMBYism, parking requirements, and lengthy entitlement timelines; (5) Policy toolkit — inclusionary zoning (mandatory vs. voluntary), density bonuses, public land disposition, property tax abatements, and community land trusts. Prioritize three interventions that would have the greatest impact per dollar of public subsidy.","tags":["affordable-housing","policy","development","community"],"author":"AINOW","created":"2024-02-15T16:55:00Z","featured":true},

    {"id":"re-85","title":"Community Land Trust Development Model","prompt":"You are a community land trust (CLT) executive and affordable homeownership expert. Explain the CLT model to a city council considering funding the launch of a new CLT in their community. Cover: (1) The fundamental structure — how the CLT retains ownership of the land while selling the housing unit to a low-income homebuyer, creating permanent affordability through a 99-year ground lease; (2) The resale formula — how CLTs balance individual wealth-building for the homeowner with preserving affordability for future buyers (typical resale formulas: appraisal-based fixed percentage, index-based, or itemized improvements method); (3) Financial modeling — a sample transaction where the city contributes a $180,000 land subsidy, the homebuyer purchases the unit for $220,000 (market value $400,000), and the unit is resold after 10 years; calculate the buyer's equity gain, the resale price, and the subsidy retained; (4) Stewardship obligations — CLT monitoring of ground lease compliance, delinquency intervention, and resale administration; (5) Funding sources — federal HOME and CDBG grants, state housing trust funds, philanthropic capital, and inclusionary zoning fees; (6) Scale and national examples — cite Burlington Community Land Trust (Champlain Housing Trust) as the oldest and largest, and what lessons other cities have learned.","tags":["affordable-housing","community-land-trust","homeownership","policy"],"author":"AINOW","created":"2024-02-15T17:00:00Z","featured":false},

    {"id":"re-86","title":"Workforce Housing Investment Strategy","prompt":"You are a real estate investment manager specializing in workforce housing. Define workforce housing (typically 60-120% AMI renters and owners), explain why it represents a distinct investment opportunity compared to both luxury multifamily and LIHTC affordable housing, and build an investment thesis for a $75M workforce housing fund. Address: (1) Supply gap — why workforce housing is the most undersupplied segment of the market (LIHTC subsidizes deep affordability, market-rate developers build luxury, leaving the middle squeezed); (2) Investment strategy — NOAH preservation (acquiring and preserving existing affordable multifamily without income restrictions), moderate rehabilitation, and mission-aligned operations; (3) Return profile — typical risk-adjusted returns (7-10% IRR), cap rate ranges, and how workforce housing cap rates compare to luxury multifamily; (4) Impact measurement — how to measure and report on affordability preservation, resident outcomes, and community impact for ESG-motivated limited partners; (5) Regulatory risk — the threat of rent control legislation, inclusionary zoning requirements on repositioned assets, and source-of-income discrimination laws; (6) Exit strategy — who buys workforce housing (other impact funds, CDFIs, housing authorities) and how this affects liquidity.","tags":["affordable-housing","workforce-housing","investment","impact"],"author":"AINOW","created":"2024-02-15T17:05:00Z","featured":false},

    {"id":"re-87","title":"Inclusionary Zoning Policy Design","prompt":"You are a housing policy advisor working with a city planning department. Design a comprehensive inclusionary zoning (IZ) policy for a growing mid-size city experiencing rapidly rising housing costs. The policy must balance two competing goals: producing affordable units and not making market-rate development infeasible. Address: (1) Set-aside percentage — the economic analysis behind choosing 10% vs. 15% vs. 20% affordable set-asides, and how the percentage affects developer feasibility (show how to calculate the 'affordability gap' that must be subsidized); (2) AMI targeting — the tradeoff between targeting very low income households (30-50% AMI, which requires deeper subsidy) vs. workforce households (80-100% AMI, which is more financially feasible for developers); (3) In-lieu fee option — when and why to allow developers to pay a fee instead of providing units on-site, how to set the fee, and how the fee is deployed to produce affordable units elsewhere; (4) Off-site option — the tradeoffs of allowing off-site unit production in different neighborhoods; (5) Density bonus — how to structure a voluntary bonus program that incentivizes affordable unit production beyond the base requirement; (6) Monitoring and compliance — long-term affordability enforcement, resale restrictions, and annual compliance reporting.","tags":["affordable-housing","policy","zoning","urban-planning"],"author":"AINOW","created":"2024-02-15T17:10:00Z","featured":false},

    // --- URBAN DEVELOPMENT (88-91) ---
    {"id":"re-88","title":"Urban Infill Development Strategy","prompt":"You are an urban infill developer and planning consultant. Develop a comprehensive strategy for assembling and developing a 4-parcel infill site in a transitional urban neighborhood. The four parcels are: a vacant lot (0.4 acres), an operating surface parking lot (0.8 acres), a one-story auto repair shop (0.5 acres, month-to-month tenant), and a four-unit apartment building (0.3 acres, market-rate tenants). Total target assemblage: 2.0 acres. Develop the strategy in five phases: (1) Acquisition strategy — how to approach each owner, the order of acquisitions to avoid the 'last holdout' problem, use of a land control option vs. direct purchase, and managing seller speculation if word gets out about the assembly; (2) Environmental and regulatory risk — assessing contamination risk on the auto repair site, title encumbrances, zoning entitlement requirements for a mixed-use project; (3) Existing tenant management — relocation assistance obligations, business relocation for the auto shop, and right-to-return policies for existing residential tenants; (4) Community engagement — how to introduce the project to the neighborhood, manage opposition, and identify meaningful community benefits; (5) Development program — how to optimize the 2.0-acre site for a mixed-income mixed-use project that pencils financially and wins community support.","tags":["development","urban-infill","strategy","community"],"author":"AINOW","created":"2024-02-15T17:15:00Z","featured":false},

    {"id":"re-89","title":"Downtown Revitalization Strategy","prompt":"You are an urban economic development consultant. A mid-size Rust Belt city with a downtown core that lost 40% of its office tenancy over the past decade has hired you to develop a downtown revitalization strategy. The central business district has: 35% office vacancy, 22 vacant storefronts on the main commercial street, three surface parking lots on prime blocks, a renovated performing arts center that operates 40 weekends/year, a university satellite campus (800 students), and a commuter rail station that brings 2,200 daily riders. Develop a 5-year revitalization strategy covering: (1) Diagnosis — the root cause analysis distinguishing structural (remote work, suburbanization) from cyclical challenges; (2) Office conversion — which buildings are candidates for residential conversion and what makes them feasible (floor plate, natural light, mechanical systems); (3) Street-level activation — strategies for filling ground-floor retail including pop-up programs, reduced rent incubator leases, and targeting food/beverage and experiential tenants; (4) Housing — the argument for bringing 500-800 new downtown residents as the most impactful single intervention; (5) Public realm investment — specific streetscape, lighting, and programming interventions that change the perception and safety of the district; (6) Financing tools — TIF districts, state historic tax credits, federal EDA grants, and opportunity zone capital.","tags":["urban-development","revitalization","economic-development","strategy"],"author":"AINOW","created":"2024-02-15T17:20:00Z","featured":true},

    {"id":"re-90","title":"Zoning Reform for Housing Abundance","prompt":"You are a housing policy researcher and urban planning consultant. Make the case for comprehensive zoning reform as the primary solution to the US housing affordability crisis. Address: (1) The history of exclusionary zoning — how post-WWII single-family zoning was used to preserve racial and economic segregation and created the current supply shortage; (2) The economics of zoning restrictions — how upzoning increases land values (benefiting existing owners) while increasing housing supply (benefiting renters and future buyers), and why the net effect on affordability is positive over time; (3) 'Missing middle' housing — the case for legalizing duplexes, triplexes, ADUs, and small apartment buildings in all residential zones, citing Minneapolis, Oregon, and Auckland as case studies; (4) ADU policy design — how California's ADU legalization has produced over 100,000 new units since 2018 and what policy elements drove adoption; (5) Transit-oriented upzoning — the research on upzoning near rail stations and the policy debate between 'upzone everywhere' advocates and those who prioritize anti-displacement protections; (6) Political economy — why homeowner-dominated local governments resist upzoning and what state-level preemption strategies have overcome local opposition. Evaluate the evidence for and against the claim that upzoning without affordability requirements exacerbates displacement.","tags":["urban-development","zoning","housing-policy","affordability"],"author":"AINOW","created":"2024-02-15T17:25:00Z","featured":false},

    {"id":"re-91","title":"Brownfield Redevelopment Playbook","prompt":"You are a brownfield redevelopment specialist and environmental attorney. A developer has an opportunity to acquire a 12-acre former industrial site in an urban area for $1.8M. The site has known petroleum contamination from a former dry cleaner and underground storage tanks that were removed in 2005. The site is adjacent to a new light rail station. Develop a complete brownfield redevelopment playbook: (1) Environmental due diligence — Phase I to Phase II to remedial investigation timeline, cost estimates, and who bears liability under CERCLA if contamination is discovered post-acquisition; (2) Innocent landowner defense and bona fide prospective purchaser (BFPP) protection — what steps the developer must take to qualify for federal liability protection; (3) Remediation options — the tradeoffs between active remediation (excavation, pump and treat), monitored natural attenuation, and institutional controls (deed restrictions on use), and how each affects development timeline, cost, and end-use flexibility; (4) Funding sources — EPA Brownfields Assessment and Cleanup grants, state revolving loan funds, tax increment financing for remediation costs, and New Markets Tax Credits; (5) Development planning — which end uses (industrial vs. residential vs. mixed-use) are compatible with residual contamination and how deed restrictions affect development program and long-term value.","tags":["urban-development","brownfield","environmental","development"],"author":"AINOW","created":"2024-02-15T17:30:00Z","featured":false},

    // --- REAL ESTATE LAW BASICS (92-96) ---
    {"id":"re-92","title":"Real Estate Purchase Contract Essentials","prompt":"You are a real estate attorney. Explain the essential elements of a residential real estate purchase contract to a first-time buyer who just received a 22-page contract from their agent. Break down the contract into its key sections and explain: (1) The essential terms — how offer price, earnest money amount (and what happens to it), and closing date are defined and what flexibility exists on each; (2) Financing contingency — the specific language that protects the buyer if they cannot obtain financing, the notice deadline for invoking the contingency, and the common mistake of letting the contingency expire; (3) Inspection contingency — the inspection period timeline, the buyer's rights after receiving the inspection report (repair request, price reduction, or walk away), and what 'AS IS' addenda mean in practice; (4) Appraisal contingency — how the contingency protects the buyer if the property appraises below purchase price, and the choice between walking away vs. making up the appraisal gap; (5) Title contingency and title insurance — the difference between lender's and owner's title insurance policies and why both matter; (6) Disclosures — what the seller is legally required to disclose and common disclosure failure claims; (7) Closing costs — the buyer's closing cost obligations (origination fees, title, escrow, prorations) and what is negotiable. Flag the three clauses where buyers most commonly make costly mistakes.","tags":["legal","residential","contract","buyer-education"],"author":"AINOW","created":"2024-02-15T17:35:00Z","featured":false},

    {"id":"re-93","title":"Landlord-Tenant Law Fundamentals","prompt":"You are a landlord-tenant attorney. Provide a comprehensive overview of landlord-tenant law fundamentals for a new landlord who just purchased their first rental property. Structure the guide by the tenant lifecycle: (1) Lease formation — what must be in a written lease to be enforceable, prohibited lease provisions (waiver of tenant rights, self-help eviction clauses), and the difference between a lease and a month-to-month rental agreement; (2) Security deposits — state law variations on maximum amounts (typically 1-2 months), required handling (separate account, interest in some states), itemized accounting timeline after move-out, and the penalty for wrongful withholding; (3) Landlord entry rights — the required notice period (typically 24-48 hours), the exceptions for emergency entry, and how to document entries; (4) Habitability — the implied warranty of habitability, what constitutes a material habitability defect, and the tenant's remedies (rent withholding, repair and deduct, lease termination in severe cases); (5) Lease termination — proper notice requirements for month-to-month vs. term leases, what triggers a lease termination, and illegal lease termination methods that expose the landlord to liability; (6) The eviction process overview — notice, filing, hearing, and writ of possession. Note that laws vary significantly by state and this overview uses general principles.","tags":["legal","landlord-tenant","residential","property-management"],"author":"AINOW","created":"2024-02-15T17:40:00Z","featured":false},

    {"id":"re-94","title":"Title Insurance Deep Dive","prompt":"You are a title attorney and real estate closing specialist. Explain title insurance comprehensively to a sophisticated buyer who questions why they need to pay $2,800 for a title insurance policy on a routine residential transaction. Cover: (1) What title insurance actually insures against — a complete list of covered risks including forged deeds, undisclosed heirs, improper legal descriptions, recording errors, easements not shown in public records, and mechanic's liens from work done before closing; (2) The title search process — how the title examiner searches public records (deed history, judgment lien search, tax lien search, UCC search, court records), what a 40-year vs. full chain of title search covers, and how this search is different from a property search; (3) Lender's vs. owner's title insurance — why the lender requires a lender's policy (which protects the lender, not the buyer), and why the owner's policy (which is optional in most states) is critically important and relatively inexpensive as an add-on; (4) Enhanced vs. standard coverage — the ALTA Homeowner's Policy (2021) vs. the standard ALTA Owner's Policy and the additional covered risks in the enhanced policy; (5) How to file a title claim — the process, the title insurer's defense obligation, and realistic outcomes; (6) A real-world case study of a title defect discovered 5 years after closing.","tags":["legal","title-insurance","residential","closing"],"author":"AINOW","created":"2024-02-15T17:45:00Z","featured":false},

    {"id":"re-95","title":"Real Estate Entity Structuring for Asset Protection","prompt":"You are a real estate attorney and CPA specializing in asset protection for real estate investors. An investor owns four rental properties with a combined equity of $1.4M and is worried about liability exposure. Design a comprehensive entity structuring strategy. Address: (1) The risk of holding property in personal name — how a slip-and-fall lawsuit on one property can threaten all personal and investment assets; (2) The single-member LLC for each property — how an LLC creates a liability firewall, the 'charging order' protection for the LLC owner, and the limitations of LLCs in states with strong reverse-piercing doctrines; (3) The series LLC structure — how it works in states that permit it (Texas, Delaware, Nevada), how it creates multiple liability compartments in a single entity, and the unresolved federal tax treatment questions; (4) The holding company structure — using a management LLC to hold the operating LLCs, insulating the management entity from property-level liability; (5) Tax implications — how disregarded single-member LLCs avoid double taxation, the self-employment tax trap for active investors with LLCs, and when an S-Corp election makes sense; (6) Insurance as the first line of defense — umbrella policy, landlord liability coverage, and why insurance and entity structure work together rather than either alone being sufficient. Include cost estimates for setting up and maintaining the recommended structure.","tags":["legal","entity-structure","asset-protection","tax"],"author":"AINOW","created":"2024-02-15T17:50:00Z","featured":false},

    {"id":"re-96","title":"Real Estate Contract Dispute Analysis","prompt":"You are a real estate litigation attorney. Review the transaction scenario described below and provide a legal analysis. Identify the applicable contract provisions, assess the legal merit of each party's position, outline the potential remedies available (specific performance, earnest money retention/return, damages), and recommend a resolution strategy. Note applicable statutes of limitations and any procedural considerations.\n\n[Paste the property details, financials, or listing description]","tags":["legal","dispute-resolution","contract","litigation"],"author":"AINOW","created":"2024-02-15T17:55:00Z","featured":false},

    // --- ADDITIONAL HIGH-VALUE PROMPTS (97-100) ---
    {"id":"re-97","title":"Real Estate Portfolio Acquisition Strategy","prompt":"You are a private equity real estate portfolio strategist. A family office with $40M of equity capital is entering the real estate investment market for the first time and wants to deploy capital over 24 months. Design a complete portfolio acquisition strategy covering: (1) Asset class allocation — recommended mix across multifamily (core-plus and value-add), industrial (last-mile), and net lease (credit tenants) with rationale based on current market cycle positioning, yield requirements, and liquidity preferences; (2) Market selection — a framework for narrowing from 200+ MSAs to 6-8 target markets using population growth, job diversification, supply constraints, and regulatory environment scores; (3) Deal sourcing strategy — how family offices access deals (direct from owners, broker relationships, club deals with operating partners, programmatic JVs with regional operators) and the tradeoffs of each channel; (4) Underwriting standards — minimum return thresholds by strategy (core 6-7% levered IRR, value-add 12-15%, opportunistic 18%+), maximum leverage by asset type, and minimum DSCR requirements; (5) Portfolio construction — the optimal number of assets for diversification without over-diluting management attention; (6) Staffing and operating model — whether to build in-house acquisition and asset management capability vs. relying entirely on external operators, and the break-even asset base for in-house capability.","tags":["investment","portfolio","strategy","private-equity"],"author":"AINOW","created":"2024-02-15T18:00:00Z","featured":true},

    {"id":"re-98","title":"Real Estate Asset Management Best Practices","prompt":"You are a real estate asset manager overseeing a $280M portfolio of 12 commercial and multifamily assets on behalf of a private equity fund. Develop a comprehensive asset management framework covering: (1) Governance — monthly vs. quarterly reporting cadences, what information to include in the asset management report (financial performance vs. budget, leasing activity, capital projects, market update, 12-month outlook, variance explanation), and how to present to an investment committee; (2) Business plan execution monitoring — how to track progress against the underwritten business plan at the individual asset level (rent growth vs. underwriting, renovation pace, lease-up velocity), and when to escalate a divergence from plan; (3) Operating partner management — how to evaluate and manage third-party property managers, what SLAs to include in management agreements, and how to conduct a quarterly performance review; (4) Value creation initiatives — a systematic approach to identifying value-add opportunities at each asset (lease expirations, below-market rents, ancillary income streams, operating expense reduction); (5) Disposition timing — how to evaluate whether to hold, refinance, or sell each asset based on current market conditions, the business plan timeline, and the fund's liquidity needs; (6) Risk monitoring — early warning indicators of asset-level distress (delinquency spike, occupancy drop, debt covenant approaching threshold).","tags":["investment","asset-management","portfolio","operations"],"author":"AINOW","created":"2024-02-15T18:05:00Z","featured":false},

    {"id":"re-99","title":"Emerging Markets Real Estate Investment Analysis","prompt":"You are a global real estate investment consultant. An institutional investor is considering a $30M allocation to real estate in one of three emerging markets: (A) Mexico City, Mexico — driven by nearshoring industrial demand from companies relocating supply chains from China; (B) Bangalore, India — driven by IT sector growth, young demographics, and severe housing undersupply; (C) Warsaw, Poland — driven by EU membership stability, logistics hub growth, and post-Ukraine reconstruction opportunity. Analyze each market across six dimensions: (1) Macroeconomic and political risk — currency stability, rule of law, political continuity, and inflation/interest rate environment; (2) Real estate market fundamentals — supply/demand balance, vacancy rates, rent growth, and cap rate levels vs. local risk-free rate; (3) Foreign investment framework — ownership restrictions on foreign investors, repatriation of capital and profits, FIRPTA-equivalent taxes; (4) Available investment structures — direct ownership, joint venture with local operator, publicly traded local REITs, cross-border funds; (5) Exit liquidity — depth of buyer pool, transaction volume, and historical liquidity in downturns; (6) Currency risk — hedging costs for USD-denominated investors and historical volatility of each currency vs. USD. Provide a ranked recommendation with a specific investment vehicle and risk mitigation strategy.","tags":["investment","international","emerging-markets","strategy"],"author":"AINOW","created":"2024-02-15T18:10:00Z","featured":false},

    {"id":"re-100","title":"Real Estate Investment Thesis Review","prompt":"You are a senior real estate investment advisor at a private equity firm. Review the investment thesis and supporting data provided below. Provide a comprehensive critical analysis covering: investment rationale and market positioning, underwriting assumptions vs. current market benchmarks, risk factors not adequately addressed in the thesis, capital structure optimization suggestions, and a final investment recommendation with the three conditions that must be true for the thesis to succeed.\n\n[Paste the property details, financials, or listing description]","tags":["investment","analysis","underwriting","strategy"],"author":"AINOW","created":"2024-02-15T18:15:00Z","featured":true}

];
